const CARD_PG=[4, 5, 5, 5, 6, 7, 9, 9, 10, 12, 14, 15, 17, 18, 19, 20, 24, 25, 27, 33, 33, 34, 38, 40, 42, 44, 45, 47, 49, 52, 59, 61, 63, 64, 66, 70, 71, 72, 74, 76, 81, 85, 85, 86, 88, 90, 91, 93, 95, 97, 97, 99, 100, 102, 104, 108, 109, 111, 112, 114, 115, 117];CARDS.forEach((c,i)=>{c.pg=c.pg||CARD_PG[i];});
/* ===================== ตัวสร้างโจทย์ไม่รู้จบ ===================== */
const R=Math.random, ri=(a,b)=>a+Math.floor(R()*(b-a+1)), pick=a=>a[Math.floor(R()*a.length)];
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(R()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const uniq=a=>[...new Set(a)];
const TH=['ก','ข','ค','ง','จ','ฉ'];
const topicKey=(ch,tp)=>ch+'.'+tp;
function topicOf(ch,tp){const c=CHAPTERS.find(x=>x.id===ch);return c&&c.topics.find(t=>t.id===tp);}

/* เตรียมข้อมูลชุด */
const CLS_ST={leaf:'{m} พบมากใน{g}',camca:'{m} {g}',perm:'{m} {g}',hchem:'{m} จัดเป็น{g}',rloc:'{m} ออกฤทธิ์ผ่าน{g}',mrecl:'{m} จับกับ {g}',
  mess:'{m} เป็น{g}',celltype:'{m} เป็นเซลล์กลุ่ม{g}',bcl:'{m} เป็นโปรตีน{g}',casp:'{m} เป็น caspase กลุ่ม{g}',cg3:'{m} เป็น{g}',drugx:'{m} เป็นยากลุ่ม {g}'};
for(const S of SETS){
  S.keys=S.keys||{};
  for(const it of S.items){
    it.a=it.a||{}; it.c=it.c||[]; it.ok=it.ok||[];
    it.st=[];
    for(const k in it.a){const K=S.keys[k]; if(K) it.st.push({t:K.s.replace('{v}',it.a[k]).trim(),k,v:it.a[k]});}
    for(let f of it.f){const nd=f[0]==='~'; if(nd) f=f.slice(1); it.st.push({t:f,nd});}
    it.truth=new Set([...it.st.map(s=>s.t),...it.ok]);
  }
  for(const it of S.items){
    it.uniq=it.st.filter(s=>S.items.every(o=>o===it||!o.truth.has(s.t)) && (!s.k||S.items.every(o=>o===it||o.a[s.k]===undefined||o.a[s.k]!==s.v)));
  }
}
for(const C of CLS) C.st=C.st||CLS_ST[C.id]||null;

function falseFor(S,X){
  const out=[];
  for(const Y of S.items){ if(Y===X) continue;
    for(const s of Y.st){ if(s.nd) continue;
      if(s.k){ if(X.a[s.k]===undefined||X.a[s.k]===s.v) continue; }
      if(X.truth.has(s.t)) continue;
      out.push({t:s.t,from:Y.n});
    }}
  const seen=new Set(); return shuffle(out).filter(o=>!seen.has(o.t)&&seen.add(o.t));
}
function mc(right,wrongs){const opts=shuffle([right,...wrongs]);return {options:opts,answer:opts.indexOf(right)};}
function sumItem(S,X,n=3){return X.n+': '+shuffle(X.st.map(s=>s.t)).slice(0,n).join(' · ');}
function lc(t){return t;}

/* ---------- ชุดข้อมูลแบบตาราง ---------- */
function gIdentify(S){
  const X=pick(S.items); if(S.items.length<3) return null;
  let stem, used=[];
  if(X.c.length&&R()<.6){ stem=pick(X.c); }
  else{
    let cl;
    if(X.uniq.length&&R()<.75){ cl=shuffle(X.uniq).slice(0,ri(1,2)); }
    else{ const st=shuffle(X.st); outer: for(let i=0;i<st.length;i++)for(let j=i+1;j<st.length;j++){ if(S.items.every(o=>o===X||!(o.truth.has(st[i].t)&&o.truth.has(st[j].t)))){cl=[st[i],st[j]];break outer;} } }
    if(!cl) return null;
    const x=cl.map(s=>s.t).join(' และ ');
    stem=S.frames&&R()<.7?pick(S.frames).replace('{x}',x):'ลักษณะต่อไปนี้: '+cl.map(s=>s.t).join(' · ');
  }
  const others=shuffle(S.items.filter(o=>o!==X)).slice(0,3).map(o=>o.n);
  return {type:'สถานการณ์',stem,ask:S.ask,...mc(X.n,others),why:sumItem(S,X),key:S.id+':'+X.n};
}
function gAttr(S){
  const ks=Object.keys(S.keys).filter(k=>uniq(S.items.map(i=>i.a[k]).filter(v=>v!==undefined)).length>=3);
  if(!ks.length) return null; const k=pick(ks);
  const X=pick(S.items.filter(i=>i.a[k]!==undefined));
  const ws=shuffle(uniq(S.items.map(i=>i.a[k]).filter(v=>v!==undefined&&v!==X.a[k]))).slice(0,3);
  return {type:'ถามตรง',stem:'',ask:S.keys[k].q.replace('{n}',X.n),...mc(X.a[k],ws),why:S.items.filter(i=>i.a[k]!==undefined).map(i=>i.n+' → '+i.a[k]).join(' · '),key:S.id+':'+X.n};
}
function gNot(S){
  const X=pick(S.items); const T=shuffle(X.st.map(s=>s.t)); if(T.length<3) return null;
  const F=falseFor(S,X); if(!F.length) return null; const f=F[0];
  const r={type:'ข้อใดไม่ถูกต้อง',stem:'',ask:pick([`ข้อใดไม่ถูกต้องเกี่ยวกับ ${X.n}`,`ข้อใดไม่ใช่ลักษณะของ ${X.n}`]),...mc(f.t,T.slice(0,3)),why:`ข้อที่ผิดเป็นลักษณะของ ${f.from} · ${sumItem(S,X)}`,key:S.id+':'+X.n};
  return r;
}
function gTrue(S){
  const X=pick(S.items); if(!X.st.length) return null; const F=falseFor(S,X); if(F.length<2) return null;
  const t=pick(X.st).t; const ws=F.slice(0,3);
  return {type:'ข้อใดถูกต้อง',stem:'',ask:`ข้อใดถูกต้องเกี่ยวกับ ${X.n}`,...mc(t,ws.map(w=>w.t)),why:sumItem(S,X)+' · ตัวเลือกอื่นเป็นลักษณะของ '+uniq(ws.map(w=>w.from)).join(', '),key:S.id+':'+X.n};
}
function gCombo(S){
  const X=pick(S.items); const F=falseFor(S,X); const T=shuffle(X.st.map(s=>s.t));
  if(R()<.5){ // 3 ข้อความ มีตัวเลือก ถูกทุกข้อ
    const pats=[[1,1,0],[0,1,1],[1,0,1],[1,1,1]].filter(p=>p.filter(x=>x).length<=T.length&&p.filter(x=>!x).length<=F.length);
    if(!pats.length) return null; const p=pick(pats); let ti=0,fi=0;
    const items=p.map(v=>v?{t:T[ti++],ok:1}:{t:F[fi++].t,ok:0});
    const order=shuffle([0,1,2]); const it2=order.map(i=>items[i]);
    const optsAll=['ก และ ข','ข และ ค','ก และ ค','ก ข และ ค ถูกทุกข้อ'];
    const okL=TH.slice(0,3).filter((l,i)=>it2[i].ok); const right=okL.length===3?optsAll[3]:okL.join(' และ ');
    return {type:'แนวข้อสอบ',list:true,stem:it2.map((x,i)=>`${TH[i]}. ${x.t}`).join('\n'),ask:`ข้อใดถูกต้องเกี่ยวกับ ${X.n}`,options:optsAll,answer:optsAll.indexOf(right),
      why:it2.some(x=>!x.ok)?'ข้อความที่ผิดคือ '+it2.map((x,i)=>x.ok?null:TH[i]+'. '+x.t).filter(Boolean).join(' · '):'ทุกข้อความถูกต้อง',key:S.id+':'+X.n};
  }
  if(T.length<2||F.length<2) return null;
  const items=shuffle([{t:T[0],ok:1},{t:T[1],ok:1},{t:F[0].t,ok:0},{t:F[1].t,ok:0}]);
  const right=TH.slice(0,4).filter((l,i)=>items[i].ok).join(' และ ');
  const pairs=[];for(let i=0;i<4;i++)for(let j=i+1;j<4;j++)pairs.push(TH[i]+' และ '+TH[j]);
  return {type:'แนวข้อสอบ',list:true,stem:items.map((x,i)=>`${TH[i]}. ${x.t}`).join('\n'),ask:`ข้อใดถูกต้องเกี่ยวกับ ${X.n}`,...mc(right,shuffle(pairs.filter(p=>p!==right)).slice(0,3)),
    why:'ข้อความที่ผิดคือ '+items.map((x,i)=>x.ok?null:TH[i]+'. '+x.t).filter(Boolean).join(' · '),key:S.id+':'+X.n};
}
function gPair(S){ // ข้อใดถูกต้อง แบบมีชื่อกำกับ
  if(S.items.length<2) return null; const neg=R()<.5;
  const mk=(X,ok)=>{ if(ok){const s=pick(X.st);return s?`${X.n} ${s.t}`:null;} const F=falseFor(S,X); return F.length?`${X.n} ${F[0].t}`:null; };
  const pool=shuffle(S.items); const right=mk(pool[0],!neg); if(!right) return null;
  const ws=[]; for(let i=0;ws.length<3&&i<12;i++){ const w=mk(pick(S.items),neg); if(w&&w!==right&&!ws.includes(w)) ws.push(w); }
  if(ws.length<3) return null;
  return {type:neg?'ข้อใดไม่ถูกต้อง':'ข้อใดถูกต้อง',stem:'',ask:neg?`เกี่ยวกับ${S.title} ข้อใดไม่ถูกต้อง`:`เกี่ยวกับ${S.title} ข้อใดถูกต้อง`,...mc(right,ws),why:S.items.map(i=>sumItem(S,i,2)).join('\n'),key:S.id+':'+pool[0].n};
}

/* ---------- การจัดกลุ่ม ---------- */
function gCls(C,lv){
  let gens=[];
  if(C.groups.length>=3) gens.push('q'); gens.push('b'); if(C.gc!==null) gens.push('c');
  if(lv==='mid'&&C.st) gens=['combo']; else if(!lv&&C.st) gens.push('combo');
  const g=pick(gens);
  if(g==='q'){ const G=pick(C.groups),m=pick(G.m); const ws=shuffle(C.groups.filter(x=>x!==G)).slice(0,3).map(x=>x.n);
    return {type:'จัดกลุ่ม',stem:'',ask:C.gq.replace('{m}',m),...mc(G.n,ws),why:C.x,key:C.id+':'+m}; }
  if(g==='b'){ const G=pick(C.groups),m=pick(G.m); const other=shuffle(C.groups.filter(x=>x!==G).flatMap(x=>x.m)).slice(0,3); if(other.length<2) return null;
    return {type:'จัดกลุ่ม',stem:'',ask:C.gb.replace('{g}',G.n),...mc(m,other),why:C.x,key:C.id+':'+m}; }
  if(g==='c'){ const G=pick(C.groups.filter(x=>x.m.length>=3)); if(!G) return null; const other=pick(C.groups.filter(x=>x!==G).flatMap(x=>x.m));
    return {type:'ข้อใดไม่ใช่',stem:'',ask:(C.gc||'ข้อใดไม่ใช่{g}').replace('{g}',G.n),...mc(other,shuffle(G.m).slice(0,3)),why:C.x,key:C.id+':'+other}; }
  // combo
  const mkS=ok=>{const G=pick(C.groups),m=pick(G.m);const g2=ok?G:pick(C.groups.filter(x=>x!==G));return {t:C.st.replace('{m}',m).replace('{g}',g2.n),ok:ok?1:0};};
  const n=R()<.5?3:4; let items;
  for(let tries=0;tries<10;tries++){ const nOk=n===3?ri(2,3):2; items=shuffle([...Array(nOk)].map(()=>mkS(1)).concat([...Array(n-nOk)].map(()=>mkS(0)))); if(uniq(items.map(i=>i.t)).length===n) break; items=null; }
  if(!items) return null;
  if(n===3){ const optsAll=['ก และ ข','ข และ ค','ก และ ค','ก ข และ ค ถูกทุกข้อ']; const okL=TH.slice(0,3).filter((l,i)=>items[i].ok); const right=okL.length===3?optsAll[3]:okL.join(' และ ');
    return {type:'แนวข้อสอบ',list:true,stem:items.map((x,i)=>`${TH[i]}. ${x.t}`).join('\n'),ask:'ข้อใดถูกต้อง',options:optsAll,answer:optsAll.indexOf(right),why:C.x,key:C.id+':combo'}; }
  const right=TH.slice(0,4).filter((l,i)=>items[i].ok).join(' และ '); const pairs=[];for(let i=0;i<4;i++)for(let j=i+1;j<4;j++)pairs.push(TH[i]+' และ '+TH[j]);
  return {type:'แนวข้อสอบ',list:true,stem:items.map((x,i)=>`${TH[i]}. ${x.t}`).join('\n'),ask:'ข้อใดถูกต้อง',...mc(right,shuffle(pairs.filter(p=>p!==right)).slice(0,3)),why:C.x,key:C.id+':combo'};
}

/* ---------- ลำดับขั้นตอน ---------- */
function permStr(p){return p.map(i=>TH[i]).join(' → ');}
function gSeq(Q,force){
  const g=force||pick(Q.steps.length>=4?['order','order','next','first','last','before']:['order','order','next','first','last']);
  const why=Q.title+': '+Q.steps.join(' → '); const N=Q.noun||'ขั้นตอน';
  if(g==='order'){
    let steps=Q.steps; if(steps.length>5){const s=ri(0,steps.length-5);steps=steps.slice(s,s+5);}
    const disp=shuffle(steps.map((t,i)=>i)); // disp[j]=index ของขั้นที่แสดงที่ตัวอักษร j
    const correct=steps.map((t,i)=>disp.indexOf(i));
    const opts=new Set([permStr(correct)]); let guard=0;
    while(opts.size<4&&guard++<60){ const p=correct.slice(); const m=ri(0,2);
      if(m===0){const i=ri(0,p.length-2);[p[i],p[i+1]]=[p[i+1],p[i]];} else if(m===1){const i=ri(0,p.length-1),j=ri(0,p.length-1);[p[i],p[j]]=[p[j],p[i]];} else {p.reverse();}
      opts.add(permStr(p)); }
    if(opts.size<3) return null; const right=permStr(correct);
    return {type:'เรียงลำดับ',list:true,stem:disp.map((si,j)=>`${TH[j]}. ${steps[si]}`).join('\n'),ask:Q.ask,...mc(right,[...opts].filter(o=>o!==right)),why,key:Q.id+':order'};
  }
  const st=Q.steps;
  if(g==='next'){ const i=ri(0,st.length-2); const ws=shuffle(st.filter((t,j)=>j!==i&&j!==i+1)).slice(0,3); if(ws.length<2) return null;
    return {type:'ลำดับขั้นตอน',stem:`เกี่ยวกับ${Q.title}`,ask:`${N}ที่อยู่ถัดจาก “${st[i]}” คือข้อใด`,...mc(st[i+1],ws),why,key:Q.id+':next'}; }
  if(g==='first'||g==='last'){ const t=g==='first'?st[0]:st[st.length-1]; const ws=shuffle(st.filter(x=>x!==t)).slice(0,3);
    return {type:'ลำดับขั้นตอน',stem:`เกี่ยวกับ${Q.title}`,ask:g==='first'?`${N}ใดอยู่เป็นลำดับแรก`:`${N}ใดอยู่เป็นลำดับสุดท้าย`,...mc(t,ws),why,key:Q.id+':'+g}; }
  const i=ri(1,st.length-2); const ok=pick(st.slice(0,i)); const later=shuffle(st.slice(i+1)).slice(0,3); if(later.length<2) return null;
  return {type:'ลำดับขั้นตอน',stem:`เกี่ยวกับ${Q.title}`,ask:`${N}ใดอยู่ก่อน “${st[i]}”`,...mc(ok,later),why,key:Q.id+':before'};
}

/* ---------- ข้อเท็จจริงเดี่ยว ---------- */
function gFact(F){
  const q=pick(F.q), a=Array.isArray(F.a)?pick(F.a):F.a, ws=shuffle(F.w).slice(0,3);
  return {type:F.neg?'ข้อใดไม่ใช่':'ถามตรง',stem:'',ask:q,...mc(a,ws),why:F.x,key:'f:'+F.q[0]};
}

const GENS=[];

/* ---------- โจทย์วิเคราะห์ชุดใหม่ (AN) ---------- */
function gAN(it){
  if(it.k==='combo'){
    const T=shuffle(it.s.filter(x=>x[1])), F=shuffle(it.s.filter(x=>!x[1]));
    if(R()<.5){ // 3 ข้อความ
      const pats=[[1,1,0],[0,1,1],[1,0,1],[1,1,1]].filter(p=>p.filter(x=>x).length<=T.length&&p.filter(x=>!x).length<=F.length);
      const p=pick(pats); let ti=0,fi=0; const items=shuffle(p.map(v=>v?{t:T[ti++][0],ok:1}:{t:F[fi++][0],ok:0}));
      const optsAll=['ก และ ข','ข และ ค','ก และ ค','ก ข และ ค ถูกทุกข้อ']; const okL=TH.slice(0,3).filter((l,i)=>items[i].ok); const right=okL.length===3?optsAll[3]:okL.join(' และ ');
      return {type:'แนวข้อสอบ',an:1,list:true,stem:it.stem+'\n'+items.map((x,i)=>`${TH[i]}. ${x.t}`).join('\n'),ask:it.ask,options:optsAll,answer:optsAll.indexOf(right),why:it.x,key:'an:'+it.stem.slice(0,40)};
    }
    const items=shuffle([{t:T[0][0],ok:1},{t:T[1][0],ok:1},{t:F[0][0],ok:0},{t:F[1][0],ok:0}]);
    const right=TH.slice(0,4).filter((l,i)=>items[i].ok).join(' และ '); const pairs=[];for(let i=0;i<4;i++)for(let j=i+1;j<4;j++)pairs.push(TH[i]+' และ '+TH[j]);
    return {type:'แนวข้อสอบ',an:1,list:true,stem:it.stem+'\n'+items.map((x,i)=>`${TH[i]}. ${x.t}`).join('\n'),ask:it.ask,...mc(right,shuffle(pairs.filter(p=>p!==right)).slice(0,3)),why:it.x,key:'an:'+it.stem.slice(0,40)};
  }
  return {type:'วิเคราะห์',an:1,stem:it.stem,ask:it.ask,...mc(pick(it.a),shuffle(it.w).slice(0,3)),why:it.x,key:'an:'+it.stem.slice(0,40)};
}

/* ---------- เลือกแหล่งโจทย์ตามระดับ ---------- */
// easy = ความจำ ถามตรง / mid = ข้อใดไม่ใช่ จับคู่ เรียงลำดับ ก ข ค / hard = วิเคราะห์เชิงลึก
const LV={easy:'ง่าย',mid:'ปานกลาง',hard:'ยาก'};
let QMODE='mix';
function srcLv(ch,tp,lv){
  const s=[], an=AN.filter(x=>x.ch===ch&&x.tp===tp), anN=an.filter(x=>x.lv!=='e'), anE=an.filter(x=>x.lv==='e');
  const sets=SETS.filter(S=>S.ch===ch&&S.tp===tp), cls=CLS.filter(C=>C.ch===ch&&C.tp===tp), seqs=SEQS.filter(Q=>Q.ch===ch&&Q.tp===tp);
  const fs=FACTS.filter(f=>f.ch===ch&&f.tp===tp);
  if(lv==='easy'){
    if(fs.length) s.push({w:2+fs.length*.4,run:()=>gFact(pick(fs))});
    for(const S of sets) s.push({w:1+S.items.length*.2,run:()=>pick([gIdentify,gIdentify,gTrue])(S)});
    for(const C of cls) s.push({w:2,run:()=>gCls(C,'easy')});
    for(const Q of seqs) s.push({w:1,run:()=>gSeq(Q,pick(Q.steps.length>=4?['first','last','next','before']:['first','last','next']))});
  } else if(lv==='mid'){
    if(anN.length) s.push({w:2+anN.length*.35,run:()=>gAN(pick(anN))});
    for(const S of sets) s.push({w:1+S.items.length*.2,run:()=>pick([gNot,gNot,gPair,gCombo])(S)});
    for(const C of cls) if(C.st) s.push({w:1.2,run:()=>gCls(C,'mid')});
    for(const Q of seqs) s.push({w:1.2,run:()=>gSeq(Q,'order')});
  } else {
    if(anE.length) s.push({w:3+anE.length*.5,run:()=>gAN(pick(anE))});
    const anC=anN.filter(x=>x.k==='combo'); if(anC.length) s.push({w:1+anC.length*.2,run:()=>gAN(pick(anC))});
    for(const S of sets) if(S.items.length>=4) s.push({w:.6,run:()=>gCombo(S)});
  }
  return s;
}
function sourcesFor(ch,tp,mode){
  const m=mode||QMODE;
  if(m==='mix'){ const out=[]; for(const lv of ['easy','mid','hard']) for(const x of srcLv(ch,tp,lv)) out.push({...x,lv}); return out; }
  const order={easy:['easy','mid','hard'],mid:['mid','easy','hard'],hard:['hard','mid','easy']}[m]||['easy','mid','hard'];
  for(const lv of order){ const s=srcLv(ch,tp,lv); if(s.length) return s.map(x=>({...x,lv})); }
  return [];
}
function wpick(arr,wf){const t=arr.reduce((a,x)=>a+wf(x),0);let r=R()*t;for(const x of arr){r-=wf(x);if(r<=0)return x;}return arr[arr.length-1];}
const RECENT=[];
function generate(topics,weak){
  for(let tries=0;tries<40;tries++){
    const T=wpick(topics,t=>1+(weak?weak(t):0));
    const src=sourcesFor(T.ch,T.tp); if(!src.length) continue;
    const sp=wpick(src,s=>s.w); const q=sp.run(); if(!q||!q.options||q.options.length<3||q.answer<0) continue;
    if(uniq(q.options).length!==q.options.length) continue;
    const sig=q.stem+'|'+q.ask+'|'+q.options[q.answer];
    if(RECENT.includes(sig)&&tries<30) continue;
    RECENT.push(sig); if(RECENT.length>40) RECENT.shift();
    q.ch=T.ch; q.tp=T.tp; q.lv=sp.lv; return q;
  }
  return null;
}


/* ===================== เสียงแมวน่ารัก (สังเคราะห์สดด้วย Web Audio) ===================== */
const SFX=(()=>{
  let ctx=null, bus=null;
  const ac=()=>{
    if(!ctx){ try{
      ctx=new (window.AudioContext||window.webkitAudioContext)();
      const comp=ctx.createDynamicsCompressor(); comp.threshold.value=-16; comp.ratio.value=3;
      bus=ctx.createGain(); bus.gain.value=.9; bus.connect(comp); comp.connect(ctx.destination);
    }catch(e){ctx=null;} }
    if(ctx&&ctx.state==='suspended') ctx.resume(); return ctx; };
  /* เสียงเหมียว: คลื่น sawtooth ผ่านฟอร์แมนต์ 2 ตัว (สระ "อี" ไป "อา" ไป "อู") เสียงสูงขึ้นแล้วลง */
  function blip(o){ const c=ac(); if(!c||!ST.sound) return; const {f0=720,peak=1.3,dur=.3,vol=.1,delay=0}=o; const t=c.currentTime+delay+.005;
    const os=c.createOscillator(), g=c.createGain(); os.type='sine'; const f=f0*1.25, d=Math.min(dur,.2);
    os.frequency.setValueAtTime(f,t); os.frequency.exponentialRampToValueAtTime(f*peak,t+d*.5);
    g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(vol*.7,t+.006); g.gain.exponentialRampToValueAtTime(.0001,t+d);
    os.connect(g).connect(bus); os.start(t); os.stop(t+d+.05); }
  function mew(o={}){ return blip(o);
    const c=ac(); if(!c||!ST.sound) return;
    const {f0=720,peak=1.35,end=.8,dur=.32,vol=.11,delay=0,vib=0}=o; const t=c.currentTime+delay+.005;
    const osc=c.createOscillator(); osc.type='sawtooth';
    osc.frequency.setValueAtTime(f0,t); osc.frequency.exponentialRampToValueAtTime(f0*peak,t+dur*.35); osc.frequency.exponentialRampToValueAtTime(f0*end,t+dur);
    if(vib){ const l=c.createOscillator(), lg=c.createGain(); l.frequency.value=vib; lg.gain.value=f0*.03; l.connect(lg).connect(osc.frequency); l.start(t); l.stop(t+dur+.05); }
    const mk=(type,f,q)=>{const b=c.createBiquadFilter(); b.type=type; b.frequency.value=f; b.Q.value=q; return b;};
    const f1=mk('bandpass',900,6), f2=mk('bandpass',2600,8);
    f1.frequency.setValueAtTime(700,t); f1.frequency.linearRampToValueAtTime(1150,t+dur*.4); f1.frequency.linearRampToValueAtTime(600,t+dur);
    f2.frequency.setValueAtTime(2900,t); f2.frequency.linearRampToValueAtTime(2200,t+dur);
    const g=c.createGain(); g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(vol,t+.03); g.gain.setValueAtTime(vol,t+dur*.6); g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    const lp=mk('lowpass',4200,.5), mix=c.createGain(); mix.gain.value=1;
    osc.connect(f1); osc.connect(f2); f1.connect(mix); f2.connect(mix); mix.connect(lp).connect(g).connect(bus);
    osc.start(t); osc.stop(t+dur+.05);
  }
  /* เสียงป๊อปเบาๆ เหมือนแตะอุ้งเท้า */
  function paw(f=1100,vol=.05,delay=0){ const c=ac(); if(!c||!ST.sound) return; const t=c.currentTime+delay+.005;
    const o=c.createOscillator(), g=c.createGain(); o.type='sine'; o.frequency.setValueAtTime(f*1.6,t); o.frequency.exponentialRampToValueAtTime(f*.7,t+.07);
    g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(vol,t+.005); g.gain.exponentialRampToValueAtTime(0.0001,t+.09);
    o.connect(g).connect(bus); o.start(t); o.stop(t+.12); }
  function purr(dur=1.2,vol=.05){ const c=ac(); if(!c||!ST.sound) return; const t=c.currentTime+.01;
    const n=c.createBuffer(1,Math.floor(c.sampleRate*dur),c.sampleRate), d=n.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1;
    const s=c.createBufferSource(); s.buffer=n; const lp=c.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=260;
    const am=c.createGain(); am.gain.value=0; const l=c.createOscillator(); l.frequency.value=24; const lg=c.createGain(); lg.gain.value=vol; l.connect(lg).connect(am.gain);
    const g=c.createGain(); g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(1,t+.15); g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    s.connect(lp).connect(am).connect(g).connect(bus); s.start(t); s.stop(t+dur); l.start(t); l.stop(t+dur); }
  const r=(a,b)=>a+Math.random()*(b-a);
  return {
    unlock:ac,
    tap(){ mew({f0:r(880,1040),peak:1.25,end:.9,dur:.13,vol:.055}); },
    soft(){ paw(r(950,1150)); },
    add(){ paw(1200,.05); paw(1500,.045,.07); },
    ok(){ mew({f0:820,peak:1.4,end:1.15,dur:.22,vol:.1}); mew({f0:980,peak:1.45,end:1.2,dur:.26,vol:.09,delay:.2}); },
    bad(){ mew({f0:560,peak:1.08,end:.62,dur:.5,vol:.1,vib:6}); },
    done(){ [0,.14,.28].forEach((d,i)=>mew({f0:760+i*130,peak:1.3,end:1.05,dur:.18,vol:.085,delay:d})); },
    rest(){ purr(1.6,.06); mew({f0:640,peak:1.2,end:.8,dur:.45,vol:.08,delay:.4}); },
    mew
  };
})();

