const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const sp=s=>String(s).replace(/([ก-ฮะ-ฺเ-๎])([A-Za-z0-9])/g,'$1 $2').replace(/([A-Za-z0-9⁺⁻²³₂₃₄])([ก-ฮเ-ไ])/g,'$1 $2');
const tx=s=>esc(sp(s));
const CHV=ch=>`--c:var(--c${ch});--cs:var(--c${ch}s)`;
const n2=n=>String(n).padStart(2,'0');
const chOf=id=>CHAPTERS.find(c=>c.id===id);
const allTopics=()=>CHAPTERS.flatMap(c=>c.topics.map(t=>({ch:c.id,tp:t.id,n:t.n,c})));
const acc=k=>{const s=ST.tp[k];return s&&s.all?Math.round(s.ok/s.all*100):null;};
function chAcc(ch){let o=0,a=0;for(const t of chOf(ch).topics){const s=ST.tp[topicKey(ch,t.id)];if(s){o+=s.ok;a+=s.all;}}return a?{p:Math.round(o/a*100),a,o}:null;}
const THM=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
const thDate=t=>{const d=new Date(t);return `${d.getDate()} ${THM[d.getMonth()]} ${d.getFullYear()+543}, ${n2(d.getHours())}:${n2(d.getMinutes())} น.`;};
const mmss=s=>{s=Math.max(0,Math.round(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return (h?h+':'+n2(m):m)+':'+n2(x);};
const meter=(p,cls='')=>`<span class="meter ${cls}" role="img" aria-label="${p==null?'ยังไม่เริ่ม':p+'%'}"><i style="width:${p||0}%"></i></span>`;
function ring(p,size=112,stroke=10){const r=(size-stroke)/2, c=2*Math.PI*r, v=p==null?0:p;
  return `<svg class="ring" viewBox="0 0 ${size} ${size}" style="width:${size}px;height:${size}px" aria-hidden="true"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--line)" stroke-width="${stroke}"/>${!v?'':`<circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--brand)" stroke-width="${stroke}" stroke-linecap="round" stroke-dasharray="${(c*v/100).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 ${size/2} ${size/2})"/>`}</svg>`;}
function toast(t){$$('.toast').forEach(x=>x.remove());const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.innerHTML=I.paw+'<span>'+esc(t)+'</span>';document.body.appendChild(d);setTimeout(()=>d.remove(),2000);}
const LVL=[{id:'mix',n:'ผสม',d:'สุ่มทุกระดับ'},{id:'easy',n:'ง่าย',d:'ความจำ ถามตรง'},{id:'mid',n:'ปานกลาง',d:'ไม่ใช่ จับคู่ เรียงลำดับ'},{id:'hard',n:'ยาก',d:'วิเคราะห์เชิงลึก'}];
const lvName=id=>(LVL.find(x=>x.id===id)||LVL[0]).n;
const lvBadge=lv=>lv?`<span class="lv lv-${lv}">${LV[lv]}</span>`:'';

/* กด: ยุบเล็กน้อย + เสียงเหมียว */
document.addEventListener('pointerdown',e=>{
  SFX.unlock();
  const b=e.target.closest('.rp'); if(!b||b.disabled) return;
  b.classList.add('pressing');
  if(!b.dataset.silent) (b.dataset.soft?SFX.soft:SFX.tap)();
});
['pointerup','pointercancel','pointerleave'].forEach(ev=>document.addEventListener(ev,()=>$$('.pressing').forEach(b=>b.classList.remove('pressing')),true));

/* ===================== โครงหน้า ===================== */
const UI={tab:'home',ch:null,me:'stats',q:'',open:{}};
const TABS=[['home','หน้าแรก',I.home],['learn','บทเรียน',I.learn],['cards','การ์ด',I.cards],['book','หนังสือ',I.book],['me','ของฉัน',I.chart]];
function go(tab,opt){UI.tab=tab;UI.ch=null;if(opt) Object.assign(UI,opt);render();window.scrollTo(0,0);}
function render(){
  const v=$('#view');
  if(UI.tab==='learn'&&UI.ch) v.innerHTML=chapterHTML(UI.ch);
  else v.innerHTML=({home:homeHTML,learn:learnHTML,book:bookHTML,cards:cardsHTML,me:meHTML,set:setHTML}[UI.tab]||homeHTML)();
  renderNav(); bind();
  if(UI.tab==='book') bookBind();
  if(UI.tab==='cards') cardsBind();
  if(UI.tab==='set') setBind();
  if(UI.tab==='home') examTick();
  timerPill();
}
function navBadge(id){return id==='me'&&ST.wrong.length?`<i class="badge num">${ST.wrong.length>99?'99+':ST.wrong.length}</i>`:'';}
function renderNav(){
  const cur=UI.tab;
  $('#tabs').innerHTML='<div>'+TABS.map(([id,l,ic])=>`<button class="tab rp ${cur===id?'on':''}" data-tab="${id}" ${cur===id?'aria-current="page"':''}><span class="ico">${ic}${navBadge(id)}</span>${l}</button>`).join('')+'</div>';
  const tot=ST.answered?Math.round(ST.correct/ST.answered*100):null;
  $('#side').innerHTML=`<div class="side-in">
    <button class="brand rp" data-tab="home" aria-label="Anatomy หน้าแรก">${MARK}<span>${WORD}<small>Human Anatomy · BI112</small></span></button>
    <button class="btn side-cta rp" data-build="">${I.sliders}จัดชุดโจทย์</button>
    <nav class="snav" aria-label="เมนูหลัก">${[...TABS,['set','ตั้งค่า',I.cog]].map(([id,l,ic])=>`<button class="si rp ${cur===id?'on':''}" data-tab="${id}" ${cur===id?'aria-current="page"':''}>${ic}<span>${l}</span>${navBadge(id)}</button>`).join('')}</nav>
    <div class="scard"><img src="${IMG.cat2}" alt="" class="scat"><div class="scard-h"><span>ความแม่นยำรวม</span><b class="num">${tot==null?'–':tot+'%'}</b></div>${meter(tot)}<small class="num">ทำแล้ว ${ST.answered} ข้อ</small></div>
    <div class="sfoot"><button class="iconbtn rp" data-act="theme" aria-label="${ST.theme==='dark'?'เปลี่ยนเป็นโหมดสว่าง':'เปลี่ยนเป็นโหมดมืด'}">${ST.theme==='dark'?I.sun:I.moon}</button><button class="iconbtn rp" data-act="sound" data-silent="1" aria-label="${ST.sound?'ปิดเสียง':'เปิดเสียง'}">${ST.sound?I.sOn:I.sOff}</button><span id="tp-side"></span></div></div>`;
}
function head(){
  return `<header class="top"><div class="top-in">
    <button class="brand m rp" data-tab="home" aria-label="Anatomy หน้าแรก">${MARK}${WORD}</button>
    <span class="top-sp"></span><span id="tp-top"></span>
    <button class="iconbtn rp" data-act="theme" aria-label="${ST.theme==='dark'?'เปลี่ยนเป็นโหมดสว่าง':'เปลี่ยนเป็นโหมดมืด'}">${ST.theme==='dark'?I.sun:I.moon}</button>
    <button class="iconbtn rp" data-act="sound" data-silent="1" aria-label="${ST.sound?'ปิดเสียง':'เปิดเสียง'}">${ST.sound?I.sOn:I.sOff}</button>
    <button class="iconbtn rp ${UI.tab==='set'?'on':''}" data-tab="set" aria-label="ตั้งค่า">${I.cog}</button></div></header>`;
}
function pageHead(h,sub,act=''){return head()+`<div class="wrap"><div class="ptitle"><div><h1>${h}</h1>${sub?`<p>${sub}</p>`:''}</div>${act}</div>`;}
const lvSeg=(cur,attr='data-diff')=>`<div class="lvseg" role="radiogroup" aria-label="ระดับความยาก">${LVL.map(d=>`<button class="ls rp ${cur===d.id?'on':''} ls-${d.id}" role="radio" aria-checked="${cur===d.id}" ${attr}="${d.id}"><b>${d.n}</b><small>${d.d}</small></button>`).join('')}</div>`;

/* ---------- หน้าแรก ---------- */
function homeHTML(){
  const last=ST.sessions[0], tot=ST.answered?Math.round(ST.correct/ST.answered*100):null, nT=allTopics().length;
  return head()+`<div class="wrap">
   ${examHTML()}
   <section class="hero">
    <div class="hero-main">
     <p class="eyebrow num">Human Anatomy · BI112 · บทที่ 1 ถึง 7</p>
     <h1>ทบทวนกายวิภาค<br><span class="hl">ครบทุกระบบ</span></h1>
     <p class="lede">โจทย์สุ่มใหม่ไม่รู้จบ ${nT} หัวข้อ ทุกข้อมีเฉลยพร้อมเหตุผล และบอกระดับ ง่าย ปานกลาง ยาก</p>
     <h2 class="mini">เลือกระดับ</h2>
     ${lvSeg(ST.diff)}
     <div class="cta-row"><button class="btn lg rp" data-play="all">${I.play}เริ่มทำโจทย์ทุกบท</button>
      <button class="btn ghost lg rp" data-build="">${I.sliders}เลือกบทและหัวข้อเอง</button></div>
    </div>
    <div class="hero-side">
     <img class="hero-cat" src="${IMG.cat1}" alt="">
     <div class="hero-stat"><div class="ring-w">${ring(tot,96,9)}<span class="ring-v"><b class="num">${tot==null?'–':tot+'%'}</b><small>แม่นยำ</small></span></div>
      <dl class="kv"><div><dt>ทำแล้ว</dt><dd class="num">${ST.answered}</dd></div><div><dt>ตอบถูก</dt><dd class="num">${ST.correct}</dd></div><div><dt>ถูกติดกัน</dt><dd class="num">${ST.best}</dd></div></dl></div>
     <p class="last">${last?`รอบล่าสุด ${esc(last.title)} ถูก ${last.ok} จาก ${last.n}`:'ทำข้อแรกแล้วสถิติจะขึ้นตรงนี้'}</p>
    </div>
   </section>
   <div class="sec"><div><h2>บทเรียน</h2><p>แตะบทเพื่อดูหัวข้อ แล้วเลือกฝึกทีละหัวข้อหรือทั้งบท</p></div><button class="link rp" data-tab="learn">ดูทั้งหมด ${I.chev}</button></div>
   <div class="chgrid">${CHAPTERS.map(chCard).join('')}</div>
   <div class="sec"><div><h2>ทบทวนแบบอื่น</h2></div></div>
   <div class="tools">
    <button class="tool rp" data-tab="cards"><span class="tool-ic">${I.cards}</span><span><b>การ์ดสรุป</b><small>${CARDS.length} ใบ ครบ 7 บท</small></span>${I.chev}</button>
    <button class="tool rp" data-tab="book"><span class="tool-ic">${I.book}</span><span><b>อ่านหนังสือ</b><small>สมุดสรุป ${BOOK.n} หน้า ซูมได้</small></span>${I.chev}</button>
    <button class="tool rp" data-me="wrong"><span class="tool-ic">${I.alert}</span><span><b>ข้อที่เคยผิด</b><small>${ST.wrong.length?ST.wrong.length+' ข้อ พร้อมเฉลย':'ตอบผิดแล้วข้อจะมารอที่นี่'}</small></span>${I.chev}</button>
    <button class="tool rp" data-act="timer"><span class="tool-ic">${I.timer}</span><span><b>ตั้งเวลาอ่านหรือทำข้อสอบ</b><small>นับถอยหลัง และเตือนพักสายตาทุก ${ST.rest.min} นาที</small></span>${I.chev}</button>
   </div></div>`;
}
function chCard(c){const a=chAcc(c.id);
  return `<button class="chc rp" data-ch="${c.id}" style="${CHV(c.id)}">
    <span class="chc-top"><span class="chc-no num">บทที่ ${c.id}</span><span class="chc-ic">${chIco(c.id)}</span></span>
    <span class="chc-t">${esc(c.name)}</span><span class="chc-en">${esc(c.en)}</span>
    <span class="chc-ft"><span class="num">${c.topics.length} หัวข้อ${a?` · ${a.a} ข้อ`:''}</span><b class="num">${a?a.p+'%':'ใหม่'}</b></span>${meter(a&&a.p)}</button>`;}

/* ---------- บทเรียน ---------- */
function topicRow(ch,t){const k=topicKey(ch,t.id), a=acc(k), s=ST.tp[k];
  return `<button class="trow rp" data-topic="${k}" style="${CHV(ch)}"><span class="trow-b"><b>${esc(t.n)}</b><small class="num">${s?`ทำแล้ว ${s.all} ข้อ`:'ยังไม่เคยทำ'}</small></span>
   <span class="macc num ${a==null?'new':a>=80?'hi':a>=50?'mid':'lo'}">${a==null?'ใหม่':a+'%'}</span><span class="trow-go">${I.play}</span></button>`;}
function learnHTML(){
  const q=UI.q.trim().toLowerCase();
  const hit=q?allTopics().filter(t=>(t.n+' '+t.c.name+' '+t.c.en+' บทที่ '+t.ch).toLowerCase().includes(q)):null;
  return pageHead('บทเรียน',`${CHAPTERS.length} บท · ${allTopics().length} หัวข้อ · แตะหัวข้อเพื่อเริ่มทำโจทย์`,`<button class="btn ghost rp" data-build="">${I.sliders}จัดชุดโจทย์</button>`)+
   `<label class="search" for="q">${I.search}<input id="q" type="search" placeholder="ค้นหาหัวข้อ เช่น กะโหลก, cranial nerve, epidermis" value="${esc(UI.q)}" autocomplete="off" aria-label="ค้นหาหัวข้อ"></label><div id="lres">`+
   (hit?`<div class="list">${hit.map(t=>topicRow(t.ch,{id:t.tp,n:t.n})).join('')||`<div class="empty">${I.search}<b>ไม่พบหัวข้อนี้</b><span>ลองค้นด้วยคำที่สั้นลง หรือชื่อภาษาอังกฤษ</span></div>`}</div>`
   :CHAPTERS.map(c=>`<section class="chgrp" style="${CHV(c.id)}"><header class="chgrp-h"><span class="chgrp-ic">${chIco(c.id)}</span><div><small class="num">บทที่ ${c.id}</small><b>${esc(c.name)}</b></div>
     <button class="btn sm rp" data-play="ch${c.id}">${I.play}ทั้งบท</button></header><div class="list">${c.topics.map(t=>topicRow(c.id,t)).join('')}</div></section>`).join(''))+'</div></div>';
}
function chapterHTML(id){const c=chOf(id), a=chAcc(id);
  return head()+`<div class="wrap">
   <button class="crumb rp" data-tab="learn">${I.back} บทเรียนทั้งหมด</button>
   <section class="chhero" style="${CHV(id)}">
    <div class="chhero-main"><p class="eyebrow num">บทที่ ${id} · ${esc(c.en)}</p><h1>${esc(c.name)}</h1>
     <dl class="kv row"><div><dt>หัวข้อ</dt><dd class="num">${c.topics.length}</dd></div><div><dt>ทำแล้ว</dt><dd class="num">${a?a.a:0}</dd></div><div><dt>แม่นยำ</dt><dd class="num">${a?a.p+'%':'–'}</dd></div></dl>
     <div class="cta-row"><button class="btn lg rp" data-play="ch${id}">${I.play}ทำโจทย์ทั้งบท</button><button class="btn ghost rp" data-build="${id}">${I.sliders}ตั้งค่า</button><button class="btn ghost rp" data-cards="${id}">${I.cards}การ์ด</button><button class="btn ghost rp" data-read="${id}">${I.book}อ่าน</button></div></div>
    <div class="chhero-art">${chIco(id)}</div>
   </section>
   <div class="sec"><div><h2>หัวข้อในบทนี้</h2><p>แตะเพื่อเริ่มทำ ระดับปัจจุบัน ${lvName(ST.diff)}</p></div></div>
   <div class="list">${c.topics.map(t=>topicRow(id,t)).join('')}</div></div>`;
}
function learnBind(){
  const q=$('#q'); if(!q) return;
  q.oninput=()=>{UI.q=q.value; const y=scrollY; render(); scrollTo(0,y); const n=$('#q'); n.focus(); n.setSelectionRange(n.value.length,n.value.length);};
}

/* ---------- ของฉัน: สถิติ ประวัติ ข้อผิด ---------- */
function meHTML(){
  const seg=`<div class="seg" role="tablist">${[['stats','สถิติ'],['history','ประวัติ'],['wrong','ข้อที่ผิด']].map(([id,l])=>`<button class="rp ${UI.me===id?'on':''}" role="tab" aria-selected="${UI.me===id}" data-me="${id}">${l}${id==='wrong'&&ST.wrong.length?` <span class="num">${ST.wrong.length}</span>`:''}</button>`).join('')}</div>`;
  return pageHead('ของฉัน','ความคืบหน้าทั้งหมดเก็บไว้ในเครื่องนี้')+seg+({stats:statsBody,history:historyBody,wrong:wrongBody}[UI.me]||statsBody)()+'</div>';
}
function statsBody(){
  const tot=ST.answered?Math.round(ST.correct/ST.answered*100):null;
  const byLv={easy:[0,0],mid:[0,0],hard:[0,0]}; for(const s of ST.sessions) if(s.lvc) for(const k in s.lvc){byLv[k][0]+=s.lvc[k][0];byLv[k][1]+=s.lvc[k][1];}
  return `<div class="kpis">
    <div class="kpi"><span>${I.layers} ทำไปแล้ว</span><b class="num">${ST.answered}</b><small>ข้อ</small></div>
    <div class="kpi"><span>${I.target} แม่นยำ</span><b class="num">${tot==null?'–':tot+'%'}</b><small>ถูก ${ST.correct} ข้อ</small></div>
    <div class="kpi"><span>${I.flame} ถูกติดกันสูงสุด</span><b class="num">${ST.best}</b><small>ข้อ</small></div>
    <div class="kpi"><span>${I.clock} เวลาใช้งานรวม</span><b class="num">${Math.round((ST.activeTotal||0)/60)}</b><small>นาที</small></div></div>
   <div class="sec"><div><h2>แยกตามระดับ</h2></div></div>
   <div class="panel lvbars">${['easy','mid','hard'].map(k=>{const[o,a]=byLv[k],p=a?Math.round(o/a*100):null;return `<div class="lvbar">${lvBadge(k)}<span class="num">${a?`${p}% · ${a} ข้อ`:'ยังไม่มี'}</span>${meter(p,'lv-'+k)}</div>`;}).join('')}</div>
   <div class="sec"><div><h2>รายบท</h2></div></div>
   <div class="panel bars">${CHAPTERS.map(c=>{const a=chAcc(c.id);return `<button class="bar rp" data-ch="${c.id}" style="${CHV(c.id)}"><span class="bar-ic">${chIco(c.id)}</span><span class="bar-b"><span class="bar-t"><b>บทที่ ${c.id} ${esc(c.name)}</b><span class="num">${a?a.p+'% · '+a.a+' ข้อ':'ยังไม่เริ่ม'}</span></span>${meter(a&&a.p,'ch')}</span></button>`;}).join('')}</div>`;
}
function historyBody(){
  const s=ST.sessions;
  return s.length?`<div class="list">${s.map((x,i)=>{const p=x.n?Math.round(x.ok/x.n*100):0;return `<div class="hrow" style="${x.ch?CHV(x.ch):''}"><span class="hav">${x.ch?chIco(x.ch):I.dice}</span><div class="hbody"><b>${esc(x.title)}</b><small class="num">${thDate(x.t)} · ${x.n} ข้อ · ถูก ${x.ok} · ${lvName(x.diff)}</small>${meter(p)}</div><span class="hpr num">${p}%</span><button class="btn ghost sm rp" data-again="${i}">ทำอีก</button></div>`;}).join('')}</div>`
   :`<div class="empty"><img src="${IMG.cat2}" alt="" class="empty-cat"><b>ยังไม่มีประวัติ</b><span>เริ่มทำโจทย์แล้วรอบที่ทำจะถูกบันทึกไว้ที่นี่</span><button class="btn rp" data-play="all">${I.play}เริ่มทำโจทย์</button></div>`;
}
/* ข้อผิด: แตะเพื่อกางเฉลยอ่านได้ทันที */
function wrongBody(){
  const w=ST.wrong;
  return w.length?`<div class="wtop"><p>${w.length} ข้อ · แตะข้อเพื่ออ่านเฉลย · ตอบถูกในรอบทบทวนแล้วข้อจะหายไป</p><button class="btn rp" data-wq="all">${I.play}ทบทวนทั้งหมด</button></div>
   <div class="list">${w.map((q,i)=>`<details class="wq" style="${CHV(q.ch)}"><summary class="rp" data-soft="1"><span class="wq-h"><small class="num">บทที่ ${q.ch} · ${esc(topicName(q.ch,q.tp))}</small>${lvBadge(q.lv)}</span><b>${tx(q.ask)}</b><span class="wq-ch">${I.down}</span></summary>
     ${explainHTML(q,null)}<div class="wq-act"><button class="btn ghost sm rp" data-wq="${i}">ทำข้อนี้อีกครั้ง</button></div></details>`).join('')}</div>`
   :`<div class="empty"><img src="${IMG.cat1}" alt="" class="empty-cat"><b>ยังไม่มีข้อที่ผิด</b><span>ตอบผิดเมื่อไร ข้อนั้นจะมารอพร้อมเฉลยที่นี่</span></div>`;
}
/* กล่องเฉลยใช้ร่วมกันทุกที่: คำตอบที่ถูก + ตัวเลือกทั้งหมด + เหตุผล */
function explainHTML(q,pick){
  return `<div class="ex">${q.stem?`<p class="ex-stem ${q.list?'list':''}">${tx(q.stem)}</p>`:''}
    <ol class="ex-opts">${q.options.map((o,j)=>`<li class="${j===q.answer?'r':j===pick?'w':''}"><span class="k num">${KL[j]}</span><span>${tx(o)}</span>${j===q.answer?`<i>${I.check}</i>`:j===pick?`<i>${I.x}</i>`:''}</li>`).join('')}</ol>
    ${q.why?`<div class="ex-why"><b>${I.bulb}เหตุผล</b><p>${tx(q.why)}</p></div>`:''}</div>`;
}
const topicName=(ch,tp)=>{const c=chOf(ch),t=c&&c.topics.find(x=>x.id===tp);return t?t.n:'';};

/* ---------- ตั้งค่า ---------- */
function setHTML(){
  const R=ST.rest, T=ST.timer;
  return pageHead('ตั้งค่า','')+`
   <div class="sec"><div><h2>ตั้งเวลา</h2><p>นับถอยหลังเวลาอ่านหนังสือหรือทำข้อสอบ นับเฉพาะตอนเปิดหน้าเว็บอยู่</p></div></div>
   <div class="panel" id="timer-panel">${timerPanel()}</div>
   <div class="sec"><div><h2>พักสายตา</h2><p>ใช้งานครบตามเวลาแล้วจะมีข้อความเต็มจอเตือนให้พัก ปัดออกได้</p></div></div>
   <div class="panel">
    <div class="setrow"><span><b>เตือนพักสายตา</b><small>นับเฉพาะเวลาที่เปิดหน้าเว็บอยู่ ออกจากเว็บเกิน 5 นาทีจะเริ่มนับใหม่</small></span><button class="sw rp ${R.on?'on':''}" data-act="restOn" role="switch" aria-label="เตือนพักสายตา" aria-checked="${R.on}"></button></div>
    <div class="setrow ${R.on?'':'off'}"><span><b>เตือนทุก</b><small id="rest-left">${restLeftText()}</small></span>
     <div class="stepper"><button class="iconbtn rp" data-rest="-5" aria-label="ลด 5 นาที">${I.minus}</button><b class="num"><span id="rest-min">${R.min}</span><small>นาที</small></b><button class="iconbtn rp" data-rest="5" aria-label="เพิ่ม 5 นาที">${I.plus}</button></div></div>
    <div class="setrow"><span><b>ลองดูหน้าพักสายตา</b><small>เปิดข้อความเตือนตอนนี้เลย</small></span><button class="btn ghost sm rp" data-act="restNow">${I.eye}ดูตัวอย่าง</button></div>
   </div>
   <div class="sec"><div><h2>ทั่วไป</h2></div></div>
   <div class="panel">
    <div class="setrow col"><span><b>ระดับโจทย์เริ่มต้น</b><small>ใช้กับปุ่มเริ่มทำโจทย์ทุกที่</small></span>${lvSeg(ST.diff)}</div>
    <div class="setrow"><span><b>โหมดมืด</b><small>ใช้ร่วมกันทุกแอพใน PX5</small></span><button class="sw rp ${ST.theme==='dark'?'on':''}" data-act="theme" role="switch" aria-label="โหมดมืด" aria-checked="${ST.theme==='dark'}"></button></div>
    <div class="setrow"><span><b>เสียงตอนกด</b><small>เสียงสั้นๆ เมื่อกดปุ่มและตอบ</small></span><button class="sw rp ${ST.sound?'on':''}" data-act="sound" data-silent="1" role="switch" aria-label="เสียงตอนกด" aria-checked="${ST.sound}"></button></div>
   </div>
   <button class="danger rp" data-act="reset">${I.reset} ล้างคะแนน ประวัติ และข้อที่ผิดทั้งหมด</button></div>`;
}

function bind(){
  $$('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
  $$('[data-ch]').forEach(b=>b.onclick=()=>{UI.tab='learn';UI.ch=+b.dataset.ch;render();scrollTo(0,0);});
  $$('[data-me]').forEach(b=>b.onclick=()=>{UI.me=b.dataset.me; if(UI.tab!=='me') go('me'); else {const y=scrollY;render();scrollTo(0,y);}});
  $$('[data-topic]').forEach(b=>b.onclick=()=>{const[a,c]=b.dataset.topic.split('.');startPlay({title:topicName(+a,c),ch:+a,topics:[{ch:+a,tp:c}]});});
  $$('[data-play]').forEach(b=>b.onclick=()=>{const p=b.dataset.play;
    if(p==='all') startPlay({title:'สุ่มทุกบท',topics:allTopics()});
    else {const id=+p.slice(2),c=chOf(id); startPlay({title:'บทที่ '+id+' '+c.name,ch:id,topics:c.topics.map(t=>({ch:id,tp:t.id}))});}});
  $$('[data-again]').forEach(b=>b.onclick=()=>{const s=ST.sessions[+b.dataset.again]; if(!s) return; if(s.mode==='wrong') return startWrong(); startPlay({title:s.title,ch:s.ch,topics:s.topics,diff:s.diff,focus:s.focus});});
  $$('[data-cards]').forEach(b=>b.onclick=()=>openCards(+b.dataset.cards));
  $$('[data-read]').forEach(b=>b.onclick=()=>openBookAt(+b.dataset.read));
  $$('[data-diff]').forEach(b=>b.onclick=()=>{ST.diff=b.dataset.diff;save();const y=scrollY;render();scrollTo(0,y);toast('ระดับ '+lvName(ST.diff));});
  $$('[data-build]').forEach(b=>b.onclick=()=>openBuilder(b.dataset.build?+b.dataset.build:null));
  $$('[data-wq]').forEach(b=>b.onclick=e=>{e.preventDefault();startWrong(b.dataset.wq==='all'?null:+b.dataset.wq);});
  $$('[data-act]').forEach(b=>b.onclick=()=>ACT[b.dataset.act]&&ACT[b.dataset.act](b));
  if(UI.tab==='learn'&&!UI.ch) learnBind();
}
const ACT={
  theme(){ST.theme=ST.theme==='dark'?'light':'dark';save();applyTheme();const y=scrollY;render();scrollTo(0,y);},
  sound(){ST.sound=!ST.sound;save();if(ST.sound)SFX.tap();const y=scrollY;render();scrollTo(0,y);toast(ST.sound?'เปิดเสียงแล้ว':'ปิดเสียงแล้ว');},
  reset:confirmReset,
  timer(){go('set');},
  restOn(){ST.rest.on=!ST.rest.on;save();const y=scrollY;render();scrollTo(0,y);},
  restNow(){showRest(true);},
  startOn(){ST.startScreen=!ST.startScreen;save();const y=scrollY;render();scrollTo(0,y);},
  start(){showStart();}
};
function confirmReset(){
  const L=$('#layer'); L.innerHTML=`<div class="scrim center" id="cf"><div class="dlg" role="dialog" aria-modal="true" aria-labelledby="cft"><img src="${IMG.cat2}" alt="" class="dlg-cat"><h3 id="cft">ล้างข้อมูลทั้งหมดใช่ไหม</h3><p>คะแนน ประวัติ และข้อที่ผิดจะถูกลบ แล้วเริ่มนับใหม่ ย้อนกลับไม่ได้</p><div class="btns"><button class="btn ghost rp" id="cf-no">ยกเลิก</button><button class="btn bad rp" id="cf-yes">ล้างข้อมูล</button></div></div></div>`;
  $('#cf-no').onclick=()=>L.innerHTML=''; $('#cf').onclick=e=>{if(e.target.id==='cf')L.innerHTML='';};
  $('#cf-yes').onclick=()=>{Object.assign(ST,{tp:{},best:0,answered:0,correct:0,sessions:[],wrong:[]});save();L.innerHTML='';SFX.bad();render();toast('ล้างข้อมูลเรียบร้อย');};
  $('#cf-no').focus();
}

/* ===================== จัดชุดโจทย์: บท หัวข้อ ระดับ ===================== */
const FOCUS=[{id:'all',n:'ทุกหัวข้อ'},{id:'weak',n:'เน้นจุดอ่อน'},{id:'new',n:'ยังไม่เคยทำ'}];
const BD={ch:new Set(),tp:new Set(),focus:'all',diff:'mix'};
function bdTopics(){ const chs=BD.ch.size?[...BD.ch]:CHAPTERS.map(c=>c.id); return chs.flatMap(id=>chOf(id).topics.map(t=>({ch:id,tp:t.id,n:t.n}))); }
function bdChosen(){
  let t=bdTopics(); const k=x=>topicKey(x.ch,x.tp);
  if(BD.tp.size){ const f=t.filter(x=>BD.tp.has(k(x))); if(f.length) t=f; }
  if(BD.focus==='new'){ const f=t.filter(x=>!(ST.tp[k(x)]&&ST.tp[k(x)].all)); if(f.length) t=f; }
  return t;
}
function openBuilder(ch){
  const sv=ST.builder||{};
  BD.ch=new Set(ch?[ch]:(sv.ch||[])); BD.tp=new Set(ch?[]:(sv.tp||[])); BD.focus=sv.focus||'all'; BD.diff=ST.diff||'mix';
  $('#layer').innerHTML=`<div class="scrim" id="bd"><div class="sheet bd" role="dialog" aria-modal="true" aria-labelledby="bdt" id="bd-in"></div></div>`;
  document.body.style.overflow='hidden';
  $('#bd').onclick=e=>{ if(e.target.id==='bd') bdClose(); };
  bdRender();
}
function bdClose(){ $('#layer').innerHTML=''; document.body.style.overflow=''; }
function bdKeep(){ ST.builder={ch:[...BD.ch],tp:[...BD.tp],focus:BD.focus}; ST.diff=BD.diff; save(); }
function bdRender(){
  const box=$('#bd-in'); if(!box) return;
  const one=BD.ch.size===1?chOf([...BD.ch][0]):null, tps=bdTopics(), chosen=bdChosen();
  const chip=(on,attr,label)=>`<button class="fchip rp ${on?'on':''}" ${attr} aria-pressed="${on}" data-soft="1">${label}</button>`;
  const sc=box.querySelector('.bd-body'), keep=sc?sc.scrollTop:0;
  box.innerHTML=`<header class="bd-h" ${one?`style="${CHV(one.id)}"`:''}><div><p class="eyebrow num">${one?'บทที่ '+one.id+' · '+esc(one.en):'ชุดโจทย์ของฉัน'}</p><h2 id="bdt">${one?esc(one.name):'จัดชุดโจทย์'}</h2>
     <p class="bd-sub">โจทย์สุ่มใหม่ทุกข้อ ไม่เลือกเลยจะนับทั้งหมด</p></div><button class="iconbtn rp" id="bd-x" aria-label="ปิด">${I.x}</button></header>
   <div class="bd-body">
    <section><h3>ระดับ</h3>${lvSeg(BD.diff,'data-bdf')}</section>
    <section><h3>บท</h3><div class="fchips">${chip(!BD.ch.size,'data-bch="all"','ทุกบท')}${CHAPTERS.map(c=>chip(BD.ch.has(c.id),`data-bch="${c.id}"`,`<b class="num">${c.id}</b> ${esc(c.name)}`)).join('')}</div></section>
    <section><h3>หัวข้อ <small>${BD.tp.size?BD.tp.size+' จาก '+tps.length:'ทั้งหมด '+tps.length}</small></h3><div class="fchips">${chip(!BD.tp.size,'data-btp="all"','ทุกหัวข้อ')}${tps.map(t=>{const k=topicKey(t.ch,t.tp);return chip(BD.tp.has(k),`data-btp="${k}"`,(BD.ch.size===1?'':`<b class="num">${t.ch}</b> `)+esc(t.n));}).join('')}</div></section>
    <section><h3>เน้น</h3><div class="fchips">${FOCUS.map(l=>chip(BD.focus===l.id,`data-bfo="${l.id}"`,l.n)).join('')}</div></section>
   </div>
   <footer class="bd-f"><span class="bd-n num">${chosen.length} หัวข้อ · ระดับ${lvName(BD.diff)}</span><button class="btn lg rp" id="bd-go" ${chosen.length?'':'disabled'}>${I.play}เริ่มทำ</button></footer>`;
  box.querySelector('.bd-body').scrollTop=keep;
  const tog=(set,v)=>set.has(v)?set.delete(v):set.add(v);
  box.querySelectorAll('[data-bch]').forEach(b=>b.onclick=()=>{const v=b.dataset.bch; if(v==='all') BD.ch.clear(); else tog(BD.ch,+v);
    const ok=new Set(bdTopics().map(x=>topicKey(x.ch,x.tp))); BD.tp.forEach(k=>{if(!ok.has(k)) BD.tp.delete(k);}); bdKeep(); bdRender();});
  box.querySelectorAll('[data-btp]').forEach(b=>b.onclick=()=>{const v=b.dataset.btp; if(v==='all') BD.tp.clear(); else tog(BD.tp,v); bdKeep(); bdRender();});
  box.querySelectorAll('[data-bdf]').forEach(b=>b.onclick=()=>{BD.diff=b.dataset.bdf; bdKeep(); bdRender();});
  box.querySelectorAll('[data-bfo]').forEach(b=>b.onclick=()=>{BD.focus=b.dataset.bfo; bdKeep(); bdRender();});
  $('#bd-x').onclick=bdClose;
  $('#bd-go').onclick=()=>{ const t=bdChosen(); if(!t.length) return;
    const ttl=one&&!BD.tp.size?'บทที่ '+one.id+' '+one.name:(t.length===1?t[0].n:'ชุดที่เลือก · '+t.length+' หัวข้อ');
    bdClose(); startPlay({title:ttl,ch:one?one.id:(t.length===1?t[0].ch:undefined),topics:t.map(x=>({ch:x.ch,tp:x.tp})),focus:BD.focus,diff:BD.diff}); };
}

/* ===================== หนังสือ: สมุดสรุปกายวิภาคศาสตร์ ===================== */
const BOOK={title:'สมุดสรุปกายวิภาคศาสตร์ BI112',n:117,ch:[{id:1,p:3},{id:2,p:11},{id:3,p:29},{id:4,p:57},{id:5,p:77},{id:6,p:94},{id:7,p:105}],
  pdf:[{f:'pdf/ch1-2.pdf',n:'บทที่ 1 และ 2',mb:7.4},{f:'pdf/ch3.pdf',n:'บทที่ 3',mb:6.9},{f:'pdf/ch4.pdf',n:'บทที่ 4',mb:5.6},{f:'pdf/ch5-6.pdf',n:'บทที่ 5 และ 6',mb:7.1},{f:'pdf/ch7.pdf',n:'บทที่ 7',mb:3.3}]};
const pageSrc=p=>`book/p-${String(p).padStart(3,'0')}.webp`;
const pageCh=p=>{let c=BOOK.ch[0].id;for(const x of BOOK.ch) if(p>=x.p) c=x.id;return c;};
let bookIO=null, bookSaveT=0;
function bookHTML(){
  const n=BOOK.n, cur=Math.min(n,Math.max(1,ST.bookPage||1));
  return head()+`<div class="wrap"><div class="ptitle"><div><h1>หนังสือ</h1><p>${esc(BOOK.title)} · ${n} หน้า · แตะหน้าเพื่อขยาย</p></div>
     <details class="dlmenu"><summary class="btn ghost rp">${I.dl}ดาวน์โหลด PDF</summary><div class="dlbox">${BOOK.pdf.map(x=>`<a class="dlrow rp" href="${x.f}" download>${I.dl}<span>${x.n}</span><small class="num">${x.mb} MB</small></a>`).join('')}</div></details></div></div>
   <div class="bk-top"><div class="wrap bk-bar"><div class="bk-chs" aria-label="ไปยังบท">${BOOK.ch.map(c=>`<button class="bk-ch rp ${pageCh(cur)===c.id?'on':''}" data-bkch="${c.p}" style="${CHV(c.id)}" data-soft="1"><span>${chIco(c.id)}</span>บทที่ ${c.id}</button>`).join('')}</div><span class="bk-cnt num" id="bk-cnt">หน้า <b>${cur}</b>/${n}</span></div></div>
   <div class="wrap"><div class="bk-pages" id="bk-pages">${Array.from({length:n},(_,i)=>`<figure class="bk-pg" id="pg-${i+1}" data-p="${i+1}"><button class="bk-img rp" data-zoom="${i+1}" data-silent="1" aria-label="ขยายหน้า ${i+1}"><img alt="หน้า ${i+1}" decoding="async" width="1100" height="1556"></button><figcaption class="num">หน้า ${i+1} · บทที่ ${pageCh(i+1)}</figcaption></figure>`).join('')}</div></div>`;
}
function bookBind(){
  if(bookIO) bookIO.disconnect();
  const pgs=$$('.bk-pg'); const load=f=>{const im=f.querySelector('img'); if(!im.getAttribute('src')) im.src=pageSrc(+f.dataset.p);};
  if('IntersectionObserver' in window){ bookIO=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting) load(e.target); }),{rootMargin:'1200px 0px'}); pgs.forEach(f=>bookIO.observe(f)); }
  else pgs.forEach(load);
  $$('[data-bkch]').forEach(b=>b.onclick=()=>bookGo(+b.dataset.bkch,true));
  $$('[data-zoom]').forEach(b=>b.onclick=()=>bookZoom(+b.dataset.zoom));
  const p=ST.bookPage||1; if(UI.bookJump){ bookGo(UI.bookJump,false); UI.bookJump=0; } else if(p>1) bookGo(p,false);
}
function bookGo(p,smooth){
  const el=$('#pg-'+p); if(!el) return; const top=$('.bk-top'); const off=(top?top.offsetHeight:0)+16;
  window.scrollTo({top:el.getBoundingClientRect().top+window.scrollY-off,behavior:smooth&&!LITE?'smooth':'auto'});
}
function bookScroll(){
  if(UI.tab!=='book') return;
  const top=$('.bk-top'), off=(top?top.offsetHeight:0)+innerHeight*.25;
  let cur=1; $$('.bk-pg').forEach(f=>{ if(f.getBoundingClientRect().top<off) cur=+f.dataset.p; });
  const c=$('#bk-cnt'); if(c) c.innerHTML=`หน้า <b>${cur}</b>/${BOOK.n}`;
  const ch=pageCh(cur); $$('[data-bkch]').forEach(b=>b.classList.toggle('on',pageCh(+b.dataset.bkch)===ch));
  if(cur!==ST.bookPage){ ST.bookPage=cur; clearTimeout(bookSaveT); bookSaveT=setTimeout(save,400); }
}
addEventListener('scroll',bookScroll,{passive:true});
function openBookAt(ch){ const c=BOOK.ch.find(x=>x.id===ch); UI.bookJump=c?c.p:1; go('book'); }
function bookZoom(p){
  const n=BOOK.n; let z=1; const L=$('#layer2');
  L.innerHTML=`<div class="bz" id="bz" role="dialog" aria-modal="true" aria-label="ดูหน้าหนังสือ">
    <div class="bz-bar"><button class="ib2 rp" id="bz-x" aria-label="ปิด">${I.x}</button><b id="bz-t" class="num"></b>
     <div class="bz-z"><button class="ib2 rp" id="bz-out" aria-label="ย่อ">${I.minus}</button><button class="ib2 rp" id="bz-in" aria-label="ขยาย">${I.plus}</button></div></div>
    <div class="bz-sc" id="bz-sc"><img id="bz-img" alt=""></div>
    <div class="bz-nav"><button class="btn rp" id="bz-prev">${I.back} ก่อนหน้า</button><button class="btn rp" id="bz-next">ถัดไป ${I.chev}</button></div></div>`;
  document.body.style.overflow='hidden';
  const img=$('#bz-img'), sc=$('#bz-sc');
  const show=()=>{ img.src=pageSrc(p); img.alt=`หน้า ${p}`; $('#bz-t').textContent=`หน้า ${p}/${n} · บทที่ ${pageCh(p)}`; $('#bz-prev').disabled=p<=1; $('#bz-next').disabled=p>=n; sc.scrollTo(0,0); };
  const zoom=v=>{ const cx=(sc.scrollLeft+sc.clientWidth/2)/sc.scrollWidth, cy=(sc.scrollTop+sc.clientHeight/2)/sc.scrollHeight;
    z=Math.max(1,Math.min(3.5,v)); img.style.width=(z*100)+'%';
    requestAnimationFrame(()=>{ sc.scrollLeft=cx*sc.scrollWidth-sc.clientWidth/2; sc.scrollTop=cy*sc.scrollHeight-sc.clientHeight/2; }); };
  const close=()=>{ L.innerHTML=''; if(!$('#layer').innerHTML) document.body.style.overflow=''; removeEventListener('keydown',kh,true); if(UI.tab==='book'&&!P) bookGo(p,false); };
  $('#bz-x').onclick=close; $('#bz-in').onclick=()=>zoom(z+.75); $('#bz-out').onclick=()=>zoom(z-.75);
  $('#bz-prev').onclick=()=>{ if(p>1){p--;show();} }; $('#bz-next').onclick=()=>{ if(p<n){p++;show();} };
  img.ondblclick=()=>zoom(z>1?1:2.2);
  let sx=null; sc.addEventListener('touchstart',e=>{ sx=z===1&&e.touches.length===1?e.touches[0].clientX:null; },{passive:true});
  sc.addEventListener('touchend',e=>{ if(sx==null) return; const dx=e.changedTouches[0].clientX-sx; if(Math.abs(dx)>60){ if(dx<0&&p<n){p++;show();} else if(dx>0&&p>1){p--;show();} } sx=null; });
  const kh=e=>{ e.stopPropagation(); if(e.key==='Escape') close(); else if(e.key==='ArrowRight'&&p<n){p++;show();} else if(e.key==='ArrowLeft'&&p>1){p--;show();} };
  addEventListener('keydown',kh,true); show();
}

/* ===================== การ์ดสรุป ===================== */
const cardsOf=ch=>CARDS.filter(c=>c.ch===ch);
function cardBody(c){
  return `${c.b&&c.b.length?`<ul class="cd-b">${c.b.map(x=>`<li>${tx(x)}</li>`).join('')}</ul>`:''}
   ${c.tb?`<div class="cd-tw"><table class="cd-tb"><thead><tr>${c.tb.h.map(h=>`<th>${tx(h)}</th>`).join('')}</tr></thead><tbody>${c.tb.r.map(r=>`<tr>${r.map(x=>`<td>${tx(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}
   ${c.tip?`<p class="cd-tip"><b>${I.paw}จำง่ายๆ</b>${tx(c.tip)}</p>`:''}`;
}
function cardHTML(c,i){
  return `<article class="cd" style="${CHV(c.ch)}"><header class="cd-h"><span class="cd-no num">${n2(i+1)}</span><h3>${tx(c.t)}</h3></header>${cardBody(c)}
   <footer class="cd-f"><button class="cd-open rp" data-cdeck="${i}">${I.expand}ดูทีละใบ</button>${c.pg?`<button class="cd-pg rp num" data-cpg="${c.pg}">${I.book}หน้า ${c.pg}</button>`:''}</footer></article>`;
}
function cardsHTML(){
  const ch=UI.cardCh||ST.cardCh||1, list=cardsOf(ch), c=chOf(ch); let idx=0;
  const secs=c.topics.map(t=>{const cs=list.filter(x=>x.tp===t.id); if(!cs.length) return '';
    return `<div class="cd-sec"><div><small class="num">หัวข้อ</small><h2>${esc(t.n)}</h2></div><button class="link rp" data-topic="${topicKey(ch,t.id)}">ฝึกโจทย์ ${I.chev}</button></div><div class="cd-grid">${cs.map(x=>cardHTML(x,idx++)).join('')}</div>`;}).join('');
  return head()+`<div class="wrap"><div class="ptitle"><div><h1>การ์ดสรุป</h1><p>${CARDS.length} ใบ จาก ${CHAPTERS.length} บท ย่อจากสมุดสรุป</p></div></div></div>
   <div class="bk-top"><div class="wrap bk-bar"><div class="bk-chs" role="tablist" aria-label="เลือกบท">${CHAPTERS.map(x=>`<button class="bk-ch rp ${x.id===ch?'on':''}" role="tab" aria-selected="${x.id===ch}" data-cch="${x.id}" style="${CHV(x.id)}" data-soft="1"><span>${chIco(x.id)}</span>บทที่ ${x.id}</button>`).join('')}</div></div></div>
   <div class="wrap"><section class="cd-hero" style="${CHV(ch)}"><div><p class="eyebrow num">บทที่ ${ch} · ${esc(c.en)}</p><h2>${esc(c.name)}</h2><p>${list.length} ใบ · ${c.topics.length} หัวข้อ</p></div>
    <div class="cta-row"><button class="btn rp" data-cdeck="0">${I.play}ทบทวนทีละใบ</button><button class="btn ghost rp" data-play="ch${ch}">ฝึกโจทย์บทนี้</button></div></section>
    ${secs||'<div class="empty"><b>ยังไม่มีการ์ดในบทนี้</b></div>'}
    <div class="cd-next">${ch<7?`<button class="btn ghost lg rp" data-cch="${ch+1}">การ์ดบทที่ ${ch+1} ${I.arrow}</button>`:''}</div></div>`;
}
function cardsBind(){
  $$('[data-cch]').forEach(b=>b.onclick=()=>openCards(+b.dataset.cch));
  $$('[data-cdeck]').forEach(b=>b.onclick=()=>cardDeck(UI.cardCh||ST.cardCh||1,+b.dataset.cdeck));
  $$('[data-cpg]').forEach(b=>b.onclick=()=>{UI.bookJump=+b.dataset.cpg;go('book');});
}
function openCards(ch){ UI.cardCh=ch; ST.cardCh=ch; save(); go('cards'); }
function cardDeck(ch,start){
  const list=cardsOf(ch); if(!list.length) return; let i=Math.max(0,Math.min(start||0,list.length-1));
  const L=$('#layer'); document.body.style.overflow='hidden';
  L.innerHTML=`<div class="dk" id="dk" role="dialog" aria-modal="true" aria-label="การ์ดสรุป บทที่ ${ch}" style="${CHV(ch)}">
    <header class="dk-h"><button class="iconbtn rp" id="dk-x" aria-label="ปิด">${I.x}</button><div class="dk-t"><b>บทที่ ${ch} · ${esc(chOf(ch).name)}</b><small class="num" id="dk-n"></small></div></header>
    <div class="dk-bar"><i id="dk-bar"></i></div><div class="dk-stage" id="dk-st"></div>
    <footer class="dk-f"><button class="btn ghost lg rp" id="dk-p">${I.back}ก่อนหน้า</button><button class="btn lg rp" id="dk-nx">ถัดไป ${I.arrow}</button></footer></div>`;
  const draw=dir=>{const c=list[i];
    $('#dk-st').innerHTML=`<article class="cd big ${dir?'in-'+dir:''}"><p class="cd-tp">${esc(topicName(c.ch,c.tp))}</p><header class="cd-h"><h3>${tx(c.t)}</h3></header>${cardBody(c)}${c.pg?`<p class="cd-src num">สมุดหน้า ${c.pg}</p>`:''}</article>`;
    $('#dk-n').textContent=`ใบที่ ${i+1} จาก ${list.length}`; $('#dk-bar').style.width=((i+1)/list.length*100)+'%';
    $('#dk-p').disabled=i===0; $('#dk-nx').innerHTML=i===list.length-1?(ch<7?`บทที่ ${ch+1} ${I.arrow}`:`จบแล้ว ${I.check}`):`ถัดไป ${I.arrow}`;
    $('#dk-st').scrollTop=0;};
  const mv=d=>{ if(i+d<0) return; if(i+d>=list.length){ close(); if(ch<7){openCards(ch+1); cardDeck(ch+1,0);} return; } i+=d; draw(d>0?'r':'l'); };
  const key=e=>{ if(e.key==='ArrowRight') mv(1); else if(e.key==='ArrowLeft') mv(-1); else if(e.key==='Escape') close(); };
  const close=()=>{ L.innerHTML=''; document.body.style.overflow=''; removeEventListener('keydown',key); };
  $('#dk-x').onclick=close; $('#dk-p').onclick=()=>mv(-1); $('#dk-nx').onclick=()=>mv(1);
  addEventListener('keydown',key);
  let sx=0,sy=0; const st=$('#dk-st');
  st.addEventListener('touchstart',e=>{sx=e.touches[0].clientX;sy=e.touches[0].clientY;},{passive:true});
  st.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy; if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.4) mv(dx<0?1:-1);},{passive:true});
  draw();
}

/* ===================== ทำโจทย์ ===================== */
let P=null;
const KL=['A','B','C','D','E'];
const qSig=q=>q.ask+'|'+q.stem+'|'+q.options[q.answer];
function weakFn(t){const s=ST.tp[topicKey(t.ch,t.tp)]; if(!s||!s.all) return .6; return Math.min(3,(s.all-s.ok)*3/(s.all+2));}
/* การ์ดที่ตรงกับโจทย์มากที่สุด (นับคำที่ซ้ำกัน) */
const tok=s=>(String(s||'').toLowerCase().match(/[a-z0-9]{3,}|[ก-๙]{4,}/g)||[]);
function cardsFor(q){
  const cs=CARDS.filter(c=>c.ch===q.ch&&c.tp===q.tp);
  const want=new Set(tok([q.stem,q.ask,q.options[q.answer],q.why].join(' ')));
  const score=c=>{const w=tok([c.t,...(c.b||[]),c.tip||'',...(c.tb?[...c.tb.h,...c.tb.r.flat()]:[])].join(' '));let s=0;const seen=new Set();for(const x of w) if(want.has(x)&&!seen.has(x)){seen.add(x);s+=x.length>6?2:1;}return s;};
  return cs.map(c=>({c,s:score(c)})).sort((a,b)=>b.s-a.s).map(x=>x.c);
}
function startPlay(o){ P=Object.assign({mode:'normal',n:0,ok:0,streak:0,bestRun:0,log:[]},o); P.diff=P.diff||ST.diff||'mix'; openPlayer(); next(); }
function startWrong(i){
  if(!ST.wrong.length){toast('ยังไม่มีข้อที่ผิด');return;}
  const qs=i!=null?[ST.wrong[i]]:shuffle(ST.wrong);
  P={title:i!=null?'ทำข้อที่ผิดอีกครั้ง':'ทบทวนข้อที่ผิด',mode:'wrong',queue:qs.map(q=>JSON.parse(JSON.stringify(q))),n:0,ok:0,streak:0,bestRun:0,log:[],topics:[]};
  openPlayer(); next();
}
function openPlayer(){
  const tag=P.mode==='wrong'?'ทบทวนข้อที่ผิด':'ระดับ'+lvName(P.diff)+(P.focus&&P.focus!=='all'?' · '+(FOCUS.find(f=>f.id===P.focus)||{}).n:'');
  $('#layer').innerHTML=`<div class="player" id="pl">
   <div class="pbar"><div class="pbar-in">
    <button class="iconbtn rp" id="pl-x" aria-label="จบรอบและดูสรุป">${I.x}</button>
    <div class="tt"><b>${esc(P.title)}</b><small class="num" id="pl-sub"></small></div>
    <span id="tp-pl"></span>
    <button class="btn ghost sm rp" id="pl-log" title="เฉลยข้อที่ทำไปแล้วในรอบนี้">${I.bulb}<span>เฉลยรอบนี้</span></button></div>
    <div class="pstats"><span class="pst"><small>ถูก</small><b class="num"><span id="s-ok">0</span>/<span id="s-all">0</span></b></span>
     <span class="pst" id="s-fire"><small>${I.flame}ติดกัน</small><b class="num" id="s-st">0</b></span><span class="ptag">${esc(tag)}</span></div>
    <div class="pline"><i id="s-line"></i></div></div>
   <div class="pl-sc" id="pl-sc"><div class="stage" id="stage"></div></div>
   <div class="pact" id="pact"></div></div>`;
  document.body.style.overflow='hidden';
  $('#pl-x').onclick=finish; $('#pl-log').onclick=showLog;
  timerPill();
}
function stats(){ $('#s-ok').textContent=P.ok; $('#s-all').textContent=P.n; $('#s-st').textContent=P.streak; $('#s-fire').classList.toggle('hot',P.streak>=3);
  const no=P.n+(P.answered?0:1);
  $('#pl-sub').textContent=P.mode==='wrong'?`ข้อที่ ${no} · เหลือ ${P.queue.length+(P.answered?0:1)} ข้อ`:'ข้อที่ '+no+' · สุ่มไม่รู้จบ';
  $('#s-line').style.width=(P.mode==='wrong'?(P.n/(P.n+P.queue.length+(P.answered?0:1)))*100:(P.n?P.ok/P.n*100:0))+'%'; }
function pickTopics(){
  let t=P.topics;
  if(P.focus==='new'){ const f=t.filter(x=>!(ST.tp[topicKey(x.ch,x.tp)]&&ST.tp[topicKey(x.ch,x.tp)].all)); if(f.length) t=f; }
  return t;
}
function next(){
  let q;
  if(P.mode==='wrong'){ q=P.queue.shift(); if(!q) return finish(); const right=q.options[q.answer]; q.options=shuffle(q.options); q.answer=q.options.indexOf(right); }
  else { QMODE=P.diff; q=generate(pickTopics(),P.focus==='weak'?(t=>weakFn(t)*4):weakFn); }
  if(!q){ toast('สร้างโจทย์ไม่ได้'); return finish(); }
  P.q=q; P.answered=false; P.pick=null; renderQ(); stats();
  $('#pl-sc').scrollTop=0;
}
function renderQ(){
  const q=P.q;
  $('#stage').innerHTML=`<div class="qmeta" style="${CHV(q.ch)}"><span class="qtopic">${chIco(q.ch)}<span>บทที่ ${q.ch} · ${esc(topicName(q.ch,q.tp))}</span></span>${lvBadge(q.lv)}<span class="qtype">${esc(q.type)}</span></div>
   <div class="qcard">${q.stem?`<p class="stem ${q.list?'list':''}">${tx(q.stem)}</p>`:''}<h2 class="ask">${tx(q.ask)}</h2></div>
   <div class="opts" role="group" aria-label="ตัวเลือก">${q.options.map((o,i)=>`<button class="opt rp" data-i="${i}" data-silent="1"><span class="k num">${KL[i]}</span><span class="ot">${tx(o)}</span><span class="mk"></span></button>`).join('')}</div>
   <div id="exw"></div>`;
  $$('.opt').forEach(b=>b.onclick=()=>answer(+b.dataset.i));
  $('#pact').innerHTML=`<div class="pact-in"><span class="pact-hint">${I.paw}เลือกคำตอบที่ถูกที่สุด</span><button class="btn ghost rp" id="pl-skip">ข้ามข้อนี้</button></div>`;
  $('#pl-skip').onclick=()=>{ if(P.mode==='wrong') P.queue.push(P.q); next(); };
}
function answer(i){
  if(P.answered) return; P.answered=true; P.pick=i;
  const q=P.q, ok=i===q.answer;
  $$('.opt').forEach((b,j)=>{ b.disabled=true;
    if(j===q.answer){b.classList.add('right');b.querySelector('.mk').innerHTML=I.check;}
    else if(j===i){b.classList.add('wrong');b.querySelector('.mk').innerHTML=I.x;}
    else b.classList.add('dim'); });
  ok?SFX.ok():SFX.bad();
  P.n++; ST.answered++;
  const k=topicKey(q.ch,q.tp); const s=ST.tp[k]||(ST.tp[k]={ok:0,all:0}); s.all++;
  if(ok){ P.ok++; ST.correct++; s.ok++; P.streak++; P.bestRun=Math.max(P.bestRun,P.streak); ST.best=Math.max(ST.best,P.streak); }
  else P.streak=0;
  const sig=qSig(q);
  if(!ok){ if(!ST.wrong.some(w=>qSig(w)===sig)){ ST.wrong.unshift({ch:q.ch,tp:q.tp,lv:q.lv,type:q.type,stem:q.stem,list:q.list,ask:q.ask,options:q.options,answer:q.answer,why:q.why}); ST.wrong=ST.wrong.slice(0,200);} }
  else if(P.mode==='wrong'){ ST.wrong=ST.wrong.filter(w=>qSig(w)!==sig); }
  P.log.push({q,pick:i,ok}); save(); stats();
  /* เฉลยอยู่ใต้ตัวเลือกเสมอ ไม่ลอย ไม่หายเอง เลื่อนอ่านได้ตามปกติ */
  const cs=cardsFor(q), c0=cs[0];
  $('#exw').innerHTML=`<section class="exp ${ok?'good':'bad'}" id="exp" aria-live="polite">
     <header class="exp-h"><span class="exp-ic">${ok?I.check:I.x}</span><div><h3>${ok?'ถูกต้อง':'ยังไม่ถูก'}</h3><p>คำตอบคือ <b>${KL[q.answer]}</b> ${tx(q.options[q.answer])}</p></div>${ok?`<img src="${IMG.cat1}" alt="" class="exp-cat">`:''}</header>
     ${q.why?`<div class="exp-why"><b>${I.bulb}เหตุผล</b><p>${tx(q.why)}</p></div>`:''}
     ${c0?`<details class="exp-card"><summary class="rp" data-soft="1">${I.cards}<span>การ์ดสรุปที่เกี่ยวข้อง<small>${esc(c0.t)}</small></span>${I.down}</summary><article class="cd flat" style="${CHV(c0.ch)}"><header class="cd-h"><h3>${tx(c0.t)}</h3></header>${cardBody(c0)}</article></details>`:''}
     <div class="exp-act">${c0&&c0.pg?`<button class="btn ghost sm rp" data-pg="${c0.pg}">${I.book}เปิดสมุดหน้า ${c0.pg}</button>`:''}</div></section>`;
  $$('#exp [data-pg]').forEach(b=>b.onclick=()=>bookZoom(+b.dataset.pg));
  const last=P.mode==='wrong'&&!P.queue.length;
  $('#pact').innerHTML=`<div class="pact-in"><button class="btn ghost rp" id="pl-see">${I.down}อ่านเฉลย</button><button class="btn lg rp" id="pl-next">${last?'ดูสรุป':'ข้อต่อไป'} ${I.arrow}</button></div>`;
  $('#pl-see').onclick=()=>$('#exp').scrollIntoView({behavior:LITE?'auto':'smooth',block:'start'});
  $('#pl-next').onclick=()=>last?finish():next();
  requestAnimationFrame(()=>{ const e=$('#exp'), sc=$('#pl-sc'); if(!e) return; const r=e.getBoundingClientRect(), pr=$('#pact').getBoundingClientRect();
    if(r.top>pr.top-80) sc.scrollBy({top:r.top-pr.top+Math.min(r.height,240),behavior:LITE?'auto':'smooth'}); });
  $('#pl-next').focus({preventScroll:true});
}
/* เฉลยทุกข้อที่ทำไปแล้วในรอบนี้ */
function showLog(){
  const L=$('#layer2');
  const list=P.log.slice().reverse();
  L.innerHTML=`<div class="scrim" id="lg"><div class="sheet" role="dialog" aria-modal="true" aria-labelledby="lgt"><header class="sh-h"><div><h2 id="lgt">เฉลยรอบนี้</h2><small class="num">${P.log.length} ข้อ · ถูก ${P.ok}</small></div><button class="iconbtn rp" id="lg-x" aria-label="ปิด">${I.x}</button></header>
   <div class="sh-body">${list.length?list.map((x,i)=>rvItem(x,P.log.length-i,i===0)).join(''):`<div class="empty sm"><img src="${IMG.cat2}" alt="" class="empty-cat"><b>ยังไม่ได้ตอบข้อไหน</b></div>`}</div></div></div>`;
  const close=()=>{L.innerHTML='';removeEventListener('keydown',kh,true);};
  const kh=e=>{ if(e.key==='Escape'){e.stopPropagation();close();} };
  addEventListener('keydown',kh,true);
  $('#lg-x').onclick=close; $('#lg').onclick=e=>{if(e.target.id==='lg')close();};
}
function rvItem({q,pick,ok},no,open){
  return `<details class="rv ${ok?'ok':'no'}" ${open?'open':''}><summary class="rp" data-soft="1"><span class="pill ${ok?'good':'bad'}">${ok?'ถูก':'ผิด'}</span><span class="rv-q"><small class="num">ข้อ ${no} · บทที่ ${q.ch} ${lvBadge(q.lv)}</small>${tx(q.ask)}</span>${I.down}</summary>${explainHTML(q,pick)}</details>`;
}
document.addEventListener('keydown',e=>{
  if(!P||!$('#pl')||$('#layer2').innerHTML||$('#rest')) return;
  const m={a:0,b:1,c:2,d:3,e:4,'1':0,'2':1,'3':2,'4':3,'5':4}[e.key.toLowerCase()];
  if(m!=null&&!P.answered&&m<P.q.options.length) answer(m);
  else if(e.key==='Enter'&&P.answered&&document.activeElement&&!document.activeElement.closest('summary')){ e.preventDefault(); $('#pl-next').click(); }
  else if(e.key==='Escape') finish();
});
function finish(){
  if(!P) return; const p=P; P=null; document.body.style.overflow=''; $('#layer2').innerHTML='';
  if(!p.n){ $('#layer').innerHTML=''; render(); return; }
  const lvc={}; for(const x of p.log) if(x.q.lv){ const a=lvc[x.q.lv]||(lvc[x.q.lv]=[0,0]); a[1]++; if(x.ok) a[0]++; }
  ST.sessions.unshift({title:p.title,ch:p.ch,topics:p.topics,focus:p.focus||'all',diff:p.diff,mode:p.mode,n:p.n,ok:p.ok,lvc,t:Date.now()}); ST.sessions=ST.sessions.slice(0,40); save();
  SFX.done();
  const pct=Math.round(p.ok/p.n*100), wrongs=p.log.map((x,i)=>[x,i+1]).filter(([x])=>!x.ok);
  const none=`<div class="empty sm"><img src="${IMG.cat1}" alt="" class="empty-cat"><b>รอบนี้ไม่มีข้อผิดเลย</b></div>`;
  const rvl=all=>(all?p.log.map((x,i)=>[x,i+1]):wrongs).map(([x,n])=>rvItem(x,n,!x.ok&&!all)).join('')||none;
  $('#layer').innerHTML=`<div class="scrim" id="sum"><div class="sheet sum" role="dialog" aria-modal="true" aria-labelledby="sumt">
    <header class="sum-h"><div class="ring-w sm">${ring(pct,92,9)}<span class="ring-v"><b class="num">${pct}%</b></span></div>
     <div><p class="eyebrow">สรุปผลรอบนี้</p><h2 id="sumt">${pct>=80?'เก่งมากเลย':pct>=50?'ทำได้ดี':'ทบทวนอีกนิดนะ'}</h2><small>${esc(p.title)}</small></div>
     <button class="iconbtn rp" id="sum-x" aria-label="ปิด">${I.x}</button></header>
    <dl class="kv grid4"><div><dt>ทำทั้งหมด</dt><dd class="num">${p.n}</dd></div><div><dt>ตอบถูก</dt><dd class="num good">${p.ok}</dd></div><div><dt>ตอบผิด</dt><dd class="num bad">${p.n-p.ok}</dd></div><div><dt>ถูกติดกัน</dt><dd class="num">${p.bestRun}</dd></div></dl>
    <div class="sum-lv">${['easy','mid','hard'].filter(k=>lvc[k]).map(k=>`<span>${lvBadge(k)}<b class="num">${lvc[k][0]}/${lvc[k][1]}</b></span>`).join('')}</div>
    <div class="cta-row two"><button class="btn ghost lg rp" id="sum-home">${I.home}หน้าแรก</button><button class="btn lg rp" id="sum-more">${p.mode==='wrong'?'ทบทวนอีกรอบ':'ทำต่อ'} ${I.arrow}</button></div>
    <div class="seg" role="tablist"><button class="rp on" data-seg="w" role="tab">ข้อที่ผิด <span class="num">${wrongs.length}</span></button><button class="rp" data-seg="a" role="tab">ทั้งหมด <span class="num">${p.n}</span></button></div>
    <div id="rvl">${rvl(false)}</div></div></div>`;
  const close=()=>{$('#layer').innerHTML='';render();};
  $('#sum-x').onclick=close; $('#sum-home').onclick=()=>{close();go('home');};
  $('#sum-more').onclick=()=>{ $('#layer').innerHTML=''; if(p.mode==='wrong') startWrong(); else startPlay({title:p.title,ch:p.ch,topics:p.topics,focus:p.focus,diff:p.diff}); };
  $('#sum').onclick=e=>{if(e.target.id==='sum')close();};
  $$('[data-seg]').forEach(b=>b.onclick=()=>{$$('[data-seg]').forEach(x=>x.classList.toggle('on',x===b)); $('#rvl').innerHTML=rvl(b.dataset.seg==='a');});
  render();
}

/* ===================== เวลาใช้งาน: นับเฉพาะตอนเปิดหน้าเว็บอยู่ ===================== */
const AWAY_LIMIT=5*60*1000; // ออกจากเว็บเกิน 5 นาที = จบการใช้งานรอบนั้น
ST.act=Object.assign({used:0,last:0},ST.act||{});
ST.cd=Object.assign({total:0,left:0,running:false,kind:'read'},ST.cd||{});
const KIND={read:'อ่านหนังสือ',quiz:'ทำข้อสอบ'};
function sessionCheck(){
  const now=Date.now();
  if(ST.act.last&&now-ST.act.last>AWAY_LIMIT){
    const hadCd=ST.cd.total>0;
    ST.act.used=0; ST.cd={total:0,left:0,running:false,kind:ST.cd.kind};
    save();
    return hadCd?'ออกจากเว็บเกิน 5 นาที เริ่มนับเวลาใหม่และยกเลิกตัวนับถอยหลังแล้ว':'ออกจากเว็บเกิน 5 นาที เริ่มนับเวลาพักสายตาใหม่';
  }
  return '';
}
let tickN=0;
function tick(){
  if(document.visibilityState!=='visible') return;
  const now=Date.now();
  if(ST.act.last&&now-ST.act.last>AWAY_LIMIT){ const m=sessionCheck(); if(m) toast(m); }
  ST.act.last=now; ST.activeTotal=(ST.activeTotal||0)+1;
  if(ST.rest.on&&!$('#rest')&&!$('#start')){
    ST.act.used++;
    if(ST.act.used>=ST.rest.min*60){ ST.act.used=0; showRest(false); }
  }
  if(ST.cd.running&&!$('#start')){
    ST.cd.left--;
    if(ST.cd.left<=0){ ST.cd.left=0; ST.cd.running=false; save(); showTimeUp(); }
  }
  if(++tickN%10===0) save();
  timerPill(); const rl=$('#rest-left'); if(rl) rl.textContent=restLeftText();
  const td=$('#cd-big'); if(td) td.textContent=mmss(ST.cd.total?ST.cd.left:ST.timer.min*60);
}
setInterval(tick,1000);
document.addEventListener('visibilitychange',()=>{
  if(document.visibilityState==='hidden'){ ST.act.last=Date.now(); save(); }
  else { const m=sessionCheck(); if(m) toast(m); ST.act.last=Date.now(); timerPill(); if(UI.tab==='set'){const tp=$('#timer-panel'); if(tp){tp.innerHTML=timerPanel(); setBind();}} }
});
addEventListener('pagehide',()=>{ ST.act.last=Date.now(); save(); });
function restLeftText(){ if(!ST.rest.on) return 'ปิดอยู่'; const l=ST.rest.min*60-ST.act.used; return `อีก ${Math.max(1,Math.ceil(l/60))} นาทีจะเตือนครั้งถัดไป`; }

/* ---------- ป้ายเวลาที่หัวจอ ---------- */
function timerPill(){
  const C=ST.cd, on=C.total>0;
  const html=on?`<button class="tpill rp ${C.running?'run':'pause'}" data-silent="1" aria-label="ตัวนับถอยหลัง${KIND[C.kind]} เหลือ ${mmss(C.left)}">${C.running?I.timer:I.pause}<span class="num">${mmss(C.left)}</span></button>`:'';
  ['#tp-top','#tp-side','#tp-pl'].forEach(s=>{ const el=$(s); if(!el) return; if(el.dataset.h!==String(on)+C.running){ el.innerHTML=html; el.dataset.h=String(on)+C.running;
      const b=el.querySelector('.tpill'); if(b) b.onclick=()=>{ if(P){ cdToggle(); } else go('set'); }; }
    else { const n=el.querySelector('.tpill .num'); if(n) n.textContent=mmss(C.left); } });
}
/* ---------- แผงตั้งเวลา ---------- */
const PRESET=[15,25,30,45,60,90];
function timerPanel(){
  const C=ST.cd, T=ST.timer, on=C.total>0, pct=on?Math.round((1-C.left/C.total)*100):0;
  return `<div class="cd-wrap">
    <div class="cd-kind" role="radiogroup" aria-label="ประเภท">${Object.entries(KIND).map(([k,n])=>`<button class="fchip rp ${(on?C.kind:T.kind)===k?'on':''}" data-kind="${k}" role="radio" aria-checked="${(on?C.kind:T.kind)===k}" ${on?'disabled':''} data-soft="1">${k==='read'?I.book:I.learn}${n}</button>`).join('')}</div>
    <div class="cd-face"><div class="ring-w">${ring(pct,168,12)}<span class="ring-v"><b class="num" id="cd-big">${mmss(on?C.left:T.min*60)}</b><small>${on?(C.running?'กำลังนับ':'หยุดชั่วคราว'):'นาที:วินาที'}</small></span></div></div>
    ${on?'':`<div class="cd-pre">${PRESET.map(m=>`<button class="fchip rp ${T.min===m?'on':''}" data-pre="${m}" data-soft="1"><b class="num">${m}</b> นาที</button>`).join('')}</div>
     <div class="stepper c"><button class="iconbtn rp" data-cdm="-5" aria-label="ลด 5 นาที">${I.minus}</button><b class="num">${T.min}<small>นาที</small></b><button class="iconbtn rp" data-cdm="5" aria-label="เพิ่ม 5 นาที">${I.plus}</button></div>`}
    <div class="cta-row two">${on?`<button class="btn ghost lg rp" data-cd="reset">${I.reset}ยกเลิก</button><button class="btn lg rp" data-cd="toggle">${C.running?I.pause+'หยุดชั่วคราว':I.play+'นับต่อ'}</button>`
      :`<button class="btn lg rp wide" data-cd="start">${I.play}เริ่มนับถอยหลัง${KIND[T.kind]}</button>`}</div>
    <p class="cd-note">นับเฉพาะตอนเปิดหน้าเว็บอยู่ ถ้าออกจากเว็บเกิน 5 นาที ตัวนับจะถูกยกเลิก</p></div>`;
}
function cdToggle(){ ST.cd.running=!ST.cd.running; save(); timerPill(); toast(ST.cd.running?'นับเวลาต่อ':'หยุดเวลาชั่วคราว'); const tp=$('#timer-panel'); if(tp){tp.innerHTML=timerPanel(); setBind();} }
function setBind(){
  const rf=()=>{ const tp=$('#timer-panel'); if(tp){ tp.innerHTML=timerPanel(); setBind(); } timerPill(); };
  $$('[data-kind]').forEach(b=>b.onclick=()=>{ST.timer.kind=b.dataset.kind;save();rf();});
  $$('[data-pre]').forEach(b=>b.onclick=()=>{ST.timer.min=+b.dataset.pre;save();rf();});
  $$('[data-cdm]').forEach(b=>b.onclick=()=>{ST.timer.min=Math.max(5,Math.min(240,ST.timer.min+ +b.dataset.cdm));save();rf();});
  $$('[data-cd]').forEach(b=>b.onclick=()=>{ const a=b.dataset.cd;
    if(a==='start'){ ST.cd={total:ST.timer.min*60,left:ST.timer.min*60,running:true,kind:ST.timer.kind}; toast('เริ่มนับถอยหลัง '+ST.timer.min+' นาที'); }
    else if(a==='toggle'){ ST.cd.running=!ST.cd.running; }
    else { ST.cd={total:0,left:0,running:false,kind:ST.cd.kind}; }
    save(); rf(); });
  $$('[data-rest]').forEach(b=>b.onclick=()=>{ ST.rest.min=Math.max(5,Math.min(180,ST.rest.min+ +b.dataset.rest)); if(ST.act.used>=ST.rest.min*60) ST.act.used=ST.rest.min*60-60; save();
    $('#rest-min').textContent=ST.rest.min; $('#rest-left').textContent=restLeftText(); });
}

/* ---------- ข้อความเต็มจอ: พักสายตา ---------- */
function showRest(demo){
  if($('#rest')) return;
  const d=document.createElement('div'); d.id='rest'; d.className='rest'; d.setAttribute('role','dialog'); d.setAttribute('aria-modal','true'); d.setAttribute('aria-labelledby','rest-t');
  d.innerHTML=`<div class="rest-in">
    <img src="${IMG.cat3}" alt="" class="rest-cat">
    <p class="eyebrow num">${demo?'ตัวอย่าง':'ใช้งานมาแล้ว '+ST.rest.min+' นาที'}</p>
    <h2 id="rest-t">พักสายตาหน่อยนะ</h2>
    <p class="rest-tip">ละสายตาจากจอ มองไปไกลๆ ประมาณ 6 เมตร สัก 20 วินาที กะพริบตาช้าๆ แล้วค่อยกลับมาอ่านต่อ</p>
    <div class="rest-cd"><div class="ring-w">${ring(0,120,10)}<span class="ring-v"><b class="num" id="rest-s">20</b><small>วินาที</small></span></div></div>
    <button class="btn lg rp" id="rest-ok">${I.check}พักแล้ว ไปต่อ</button>
    <p class="rest-hint">ปัดขึ้น หรือกด Esc เพื่อปิด · จะเตือนอีกครั้งในอีก ${ST.rest.min} นาที</p></div>`;
  document.body.appendChild(d); SFX.rest();
  let s=20; const ringC=()=>{const c=d.querySelector('.ring');const r=(120-10)/2,C=2*Math.PI*r;c.innerHTML=`<circle cx="60" cy="60" r="${r}" fill="none" stroke="var(--line)" stroke-width="10"/><circle cx="60" cy="60" r="${r}" fill="none" stroke="var(--brand)" stroke-width="10" stroke-linecap="round" stroke-dasharray="${(C*(20-s)/20).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 60 60)"/>`;};
  const iv=setInterval(()=>{ if(!d.isConnected) return clearInterval(iv); if(document.visibilityState!=='visible') return; s--; $('#rest-s').textContent=Math.max(0,s); ringC(); if(s<=0){clearInterval(iv); $('#rest-s').textContent='0'; d.classList.add('done'); SFX.ok();} },1000);
  const close=()=>{ clearInterval(iv); d.classList.add('out'); removeEventListener('keydown',kh,true); ST.act.used=0; save(); setTimeout(()=>d.remove(),260); };
  const kh=e=>{ if(e.key==='Escape'||e.key==='Enter'){ e.preventDefault(); e.stopPropagation(); close(); } };
  addEventListener('keydown',kh,true);
  $('#rest-ok').onclick=close;
  let sy=null; d.addEventListener('touchstart',e=>{sy=e.touches[0].clientY;},{passive:true});
  d.addEventListener('touchend',e=>{ if(sy!=null&&sy-e.changedTouches[0].clientY>90) close(); sy=null; },{passive:true});
  $('#rest-ok').focus();
}
/* ---------- หมดเวลานับถอยหลัง ---------- */
function showTimeUp(){
  if($('#rest')) $('#rest').remove();
  const k=ST.cd.kind, mins=Math.round(ST.cd.total/60);
  const d=document.createElement('div'); d.id='rest'; d.className='rest up'; d.setAttribute('role','dialog'); d.setAttribute('aria-modal','true'); d.setAttribute('aria-labelledby','up-t');
  d.innerHTML=`<div class="rest-in"><img src="${IMG.cat1}" alt="" class="rest-cat"><p class="eyebrow num">ครบ ${mins} นาที</p><h2 id="up-t">หมดเวลา${KIND[k]}แล้ว</h2>
    <p class="rest-tip">${k==='quiz'?'ลองดูสรุปผลรอบนี้ แล้วทบทวนข้อที่ผิด':'เก่งมาก ลองทำโจทย์เพื่อเช็กว่าจำได้แค่ไหน'}</p>
    <div class="cta-row two"><button class="btn ghost lg rp" id="up-more">${I.plus}ต่ออีก 5 นาที</button><button class="btn lg rp" id="up-ok">${I.check}รับทราบ</button></div></div>`;
  document.body.appendChild(d); SFX.done();
  const close=()=>{ d.classList.add('out'); removeEventListener('keydown',kh,true); setTimeout(()=>d.remove(),260); ST.cd.total=ST.cd.running?ST.cd.total:0; save(); timerPill(); if(UI.tab==='set'){const tp=$('#timer-panel'); if(tp){tp.innerHTML=timerPanel(); setBind();}} };
  const kh=e=>{ if(e.key==='Escape'){ e.stopPropagation(); close(); } };
  addEventListener('keydown',kh,true);
  $('#up-ok').onclick=close;
  $('#up-more').onclick=()=>{ ST.cd={total:300,left:300,running:true,kind:k}; save(); close(); };
  $('#up-ok').focus();
}

/* ===================== นับถอยหลังวันสอบกายวิภาค (ดึงจากเว็บตารางเรียน) ===================== */
const EXAM_SRC='https://nytoff5389-boop.github.io/space-schedule/data/schedule.json';
/* สำเนาสำรอง ใช้ตอนโหลดจากเว็บตารางเรียนไม่ได้ (อัปเดต 8 พ.ย. 2569) */
const EXAM_FALLBACK=[
  {date:'2026-12-11',start:'16:30',end:'18:00',title:'สอบก่อนกลางภาค (บรรยาย บทที่ 1-4, 16%)'},
  {date:'2026-12-11',start:'18:00',end:'19:00',title:'สอบก่อนกลางภาค (ปฏิบัติการ บทที่ 1-4, 6%)'},
  {date:'2027-01-20',start:'13:00',end:'15:00',title:'สอบกลางภาค (บรรยาย บทที่ 5-7, 14%)'},
  {date:'2027-01-20',start:'15:00',end:'16:00',title:'สอบกลางภาค (ปฏิบัติการ บทที่ 5-7, 5%)'},
  {date:'2027-02-12',start:'16:30',end:'18:00',title:'สอบก่อนปลายภาค (บรรยาย บทที่ 8-11, 16%)'},
  {date:'2027-02-12',start:'18:00',end:'19:00',title:'สอบก่อนปลายภาค (ปฏิบัติการ บทที่ 8-11, 6%)'},
  {date:'2027-03-19',start:'11:30',end:'13:30',title:'สอบปลายภาค (บรรยาย บทที่ 12-15, 16%)'},
  {date:'2027-03-19',start:'13:30',end:'14:30',title:'สอบปลายภาค (ปฏิบัติการ บทที่ 12-15, 6%)'}
];
const EXAM_KEY='anatomeow.exams';
function examParse(list){
  return list.map(e=>{
    const m=String(e.title).match(/^(.*?)\s*\((.*)\)\s*$/)||[null,e.title,''];
    const inner=m[2]||'', lab=/ปฏิบัติ|lab/i.test(e.title);
    const pct=(inner.match(/(\d+(?:\.\d+)?)\s*%/)||[])[1];
    const chap=(inner.match(/บทที่\s*\d+(?:\s*[-–]\s*\d+)?/)||[''])[0];
    return {round:m[1].trim(),lab,pct:pct?pct+'%':'',chap,date:e.date,start:e.start,end:e.end,
      t0:new Date(`${e.date}T${e.start}:00+07:00`).getTime(),t1:new Date(`${e.date}T${e.end||e.start}:00+07:00`).getTime()};
  }).sort((a,b)=>a.t0-b.t0||a.lab-b.lab);
}
let EXAMS=examParse(EXAM_FALLBACK), EXAM_FROM='สำเนาในแอป';
try{ const c=JSON.parse(localStorage.getItem(EXAM_KEY)); if(c&&c.list&&c.list.length){ EXAMS=examParse(c.list); EXAM_FROM='เว็บตารางเรียน'; } }catch(e){}
function examPick(d){
  const codes=Object.entries(d.courses||{}).filter(([k,v])=>/กายวิภาค|anatomy/i.test((v.name||'')+' '+(v.en||''))).map(([k])=>k);
  return (d.exams||[]).filter(e=>codes.includes(e.code));
}
fetch(EXAM_SRC,{cache:'no-cache'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{
  const list=examPick(d); if(!list.length) return;
  EXAMS=examParse(list); EXAM_FROM='เว็บตารางเรียน';
  try{ localStorage.setItem(EXAM_KEY,JSON.stringify({list,at:Date.now()})); }catch(e){}
  const b=$('#exb'); if(b){ b.outerHTML=examHTML(); examTick(); }
}).catch(()=>{});

const TH_DAY=['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์'];
const exDate=e=>{const d=new Date(e.date+'T12:00:00+07:00');return `วัน${TH_DAY[d.getUTCDay()]}ที่ ${d.getUTCDate()} ${THM[d.getUTCMonth()]} ${d.getUTCFullYear()+543}`;};
/* รอบสอบถัดไป = วันที่มีสอบที่ยังไม่จบ ทั้งบรรยายและแล็บของวันนั้น */
function examNext(now=Date.now()){
  const up=EXAMS.find(e=>e.t1>now); if(!up) return null;
  return EXAMS.filter(e=>e.date===up.date&&e.round===up.round);
}
function examCard(e){
  return `<article class="exc ${e.lab?'lab':'lec'}" data-t0="${e.t0}" data-t1="${e.t1}">
    <header class="exc-h"><span class="exc-k">${e.lab?'Lab ปฏิบัติการ':'บรรยาย'}</span>${e.pct?`<span class="exc-p num">${e.pct}</span>`:''}</header>
    <p class="exc-ch">${esc(e.chap||e.round)}</p>
    <div class="exc-cd num" aria-live="off"><span><b data-u="d">0</b><small>วัน</small></span><span><b data-u="h">00</b><small>ชั่วโมง</small></span><span><b data-u="m">00</b><small>นาที</small></span><span><b data-u="s">00</b><small>วินาที</small></span></div>
    <p class="exc-st" data-st></p>
    <p class="exc-when">${I.clock}<span>${exDate(e)}<br><b class="num">${e.start}${e.end?' ถึง '+e.end:''} น.</b></span></p></article>`;
}
function examHTML(){
  const nx=examNext();
  if(!nx) return `<section class="exb done" id="exb"><img src="${IMG.cat1}" alt="" class="exb-cat"><div><p class="exb-k">กายวิภาคศาสตร์</p><h2>สอบครบทุกรอบแล้ว เก่งมาก</h2></div></section>`;
  const rest=EXAMS.filter(e=>!e.lab&&e.t1>Date.now()&&e.date!==nx[0].date);
  return `<section class="exb" id="exb" aria-label="นับถอยหลังวันสอบ">
    <div class="exb-top"><div><p class="exb-k">นับถอยหลังสอบกายวิภาคศาสตร์</p><h2>${esc(nx[0].round)}</h2></div><img src="${IMG.cat2}" alt="" class="exb-cat"></div>
    <div class="exb-grid ${nx.length>1?'two':''}">${nx.map(examCard).join('')}</div>
    ${rest.length?`<div class="exb-next"><span>รอบถัดไป</span>${rest.map(e=>`<span class="exb-chip num">${esc(e.round)} · ${new Date(e.date+'T12:00:00+07:00').getUTCDate()} ${THM[new Date(e.date+'T12:00:00+07:00').getUTCMonth()]}</span>`).join('')}</div>`:''}
    <p class="exb-src">ข้อมูลจาก${EXAM_FROM} · เวลาประเทศไทย</p></section>`;
}
function examTick(){
  const now=Date.now(); let ended=false;
  $$('.exc').forEach(c=>{
    const t0=+c.dataset.t0, t1=+c.dataset.t1, st=c.querySelector('[data-st]');
    if(now>=t1){ ended=true; return; }
    let s=Math.max(0,Math.floor((t0-now)/1000)); const live=now>=t0;
    c.classList.toggle('live',live); c.classList.toggle('soon',!live&&t0-now<24*3600e3);
    if(live) s=Math.floor((t1-now)/1000);
    const v={d:Math.floor(s/86400),h:n2(Math.floor(s%86400/3600)),m:n2(Math.floor(s%3600/60)),s:n2(s%60)};
    c.querySelectorAll('[data-u]').forEach(b=>{ const x=String(v[b.dataset.u]); if(b.textContent!==x) b.textContent=x; });
    const txt=live?'กำลังสอบอยู่ เหลือเวลาอีก':(t0-now<24*3600e3?'สอบพรุ่งนี้หรือวันนี้ เตรียมตัวให้พร้อม':'');
    if(st.textContent!==txt) st.textContent=txt;
  });
  if(ended){ const b=$('#exb'); if(b){ b.outerHTML=examHTML(); } }
}
setInterval(()=>{ if(document.visibilityState==='visible'&&$('#exb')) examTick(); },1000);

/* ===================== หน้าเริ่มเกม ===================== */
const ENTER_SND={currentTime:0,play(){return Promise.resolve();}};
function showStart(){
  if($('#start')) return;
  const d=document.createElement('div'); d.id='start'; d.className='start'; d.setAttribute('role','dialog'); d.setAttribute('aria-modal','true'); d.setAttribute('aria-label','หน้าเริ่ม Anatomeow');
  d.innerHTML=`<div class="st-bg" aria-hidden="true"><i class="st-dots"></i><i class="st-rays"></i></div>
   <div class="st-in">
    <div class="st-stage">
     <figure class="st-vid"><video id="st-v" src="media/clip.mp4" poster="img/clip-poster.webp" autoplay muted loop playsinline preload="auto"></video>
      <button class="st-mute rp" id="st-mute" data-silent="1" aria-label="เปิดเสียงคลิป">${I.sOff}</button></figure>
     <img class="st-yj" src="${IMG.yj}" alt="ยังเจ">
     <span class="st-bubble">มาอ่านกายวิภาค<br>กันเถอะ</span>
     <img class="st-cat" src="${IMG.cat1}" alt="">
    </div>
    <div class="st-title"><p class="st-k num">Human Anatomy · BI112</p><h1>ANATO<span>MEOW</span></h1><p class="st-sub">ทบทวนกายวิภาคบทที่ 1 ถึง 7 · โจทย์ไม่รู้จบ</p></div>
    <button class="st-go" id="st-go" data-silent="1">${I.paw}<span>ENTER</span></button>
    <p class="st-hint">กดปุ่ม หรือกด Enter เพื่อเริ่ม</p>
   </div>`;
  document.body.appendChild(d); document.body.style.overflow='hidden';
  const v=$('#st-v'); const pr=v.play(); if(pr&&pr.catch) pr.catch(()=>{});
  $('#st-mute').onclick=()=>{ v.muted=!v.muted; if(!v.muted){ v.play().catch(()=>{}); } $('#st-mute').innerHTML=v.muted?I.sOff:I.sOn; $('#st-mute').setAttribute('aria-label',v.muted?'เปิดเสียงคลิป':'ปิดเสียงคลิป'); };
  const enter=()=>{
    if(d.classList.contains('out')) return;
    try{ ENTER_SND.currentTime=0; ENTER_SND.play().catch(()=>{}); }catch(e){}
    SFX.unlock(); v.muted=true;
    d.classList.add('out'); removeEventListener('keydown',kh,true);
    setTimeout(()=>{ v.pause(); d.remove(); if(!$('#layer').innerHTML) document.body.style.overflow=''; ST.act.last=Date.now(); },LITE?150:650);
  };
  const kh=e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); e.stopPropagation(); enter(); } };
  addEventListener('keydown',kh,true);
  $('#st-go').onclick=enter; $('#st-go').focus({preventScroll:true});
}

